// Üretilen dosya: tool/ozgun/uret.py. İstatistik ve Veri Bilimi · Merkezî eğilim ve yayılım ölçüleri (her soru kendi verisini içerir) (orta).
const ozStatistics1Orta = <(String, String, List<String>, String)>[
  ('On iki kişilik bir grubun yaş ortalaması 15\'tir. Gruba 28 yaşında bir antrenör katılırsa yeni yaş ortalaması kaç olur?', '16', ['15,5', '16,5', '17'], 'İlk toplam 12 · 15 = 180\'dir. 180 + 28 = 208 ve 208 / 13 = 16 olur.'),
  ('On paketin ortalama ağırlığı 42 gramdır. Bu paketlerden 60 gramlık olanı çıkarılırsa kalan dokuz paketin ortalama ağırlığı kaç gram olur?', '40', ['38', '37,5', '39'], 'Toplam 10 · 42 = 420 gramdır. 420 − 60 = 360 ve 360 / 9 = 40 gram bulunur.'),
  ('Bir öğrencinin ilk dört sınav ortalaması 76\'dır. Beş sınavın ortalamasının 80 olması için beşinci sınavdan kaç alması gerekir?', '96', ['84', '92', '100'], 'Beş sınav toplamı 5 · 80 = 400 olmalıdır. İlk dört sınav toplamı 304 olduğundan beşinci sınav 400 − 304 = 96 olmalıdır.'),
  ('Bir veri setindeki her gözlemin aritmetik ortalamadan farkı alınıp bu farklar toplanırsa sonuç ne olur?', 'Her zaman sıfır', ['Her zaman pozitif bir sayı', 'Varyansa eşit bir değer', 'Gözlem sayısına eşit bir değer'], 'Σ(xᵢ − x̄) = Σxᵢ − n·x̄ = 0\'dır; ortalamanın üstündeki ve altındaki sapmalar birbirini tam olarak dengeler.'),
  ('Bir okulda A şubesindeki 30 öğrencinin ortalaması 68, B şubesindeki 20 öğrencinin ortalaması 78\'dir. İki şubenin birlikte ortalaması kaçtır?', '72', ['73', '70', '71,5'], 'Birleşik toplam 30 · 68 + 20 · 78 = 2040 + 1560 = 3600\'dür; 3600 / 50 = 72 bulunur. Şube sayıları eşit olmadığından 73 değildir.'),
  ('Bir öğrencinin aldığı derslerin kredileri ve notları şöyledir: 3 kredilik dersten 4, 5 kredilik dersten 3, 2 kredilik dersten 5 puan almıştır. Kredi ağırlıklı not ortalaması kaçtır?', '3,7', ['4,0', '3,5', '3,85'], 'Ağırlıklı toplam 3 · 4 + 5 · 3 + 2 · 5 = 37, toplam kredi 10\'dur; 37 / 10 = 3,7.'),
  ('Bir manav 2 kg\'ı 120 TL\'lik, 3 kg\'ı 80 TL\'lik ve 5 kg\'ı 60 TL\'lik üç tür kuruyemişi karıştırıyor. Karışımın kilogram fiyatı kaç TL olur?', '78', ['86,7', '72', '80'], 'Toplam maliyet 240 + 240 + 300 = 780 TL, toplam kütle 10 kg\'dır; 780 / 10 = 78 TL. Fiyatların düz ortalaması (86,7) miktar farkını hesaba katmaz.'),
  ('Ara sınavın %40, finalin %60 ağırlıkla değerlendirildiği bir derste ara sınavdan 65 alan bir öğrenci dönem puanının 80 olmasını istiyor. Finalden en az kaç alması gerekir?', '90', ['95', '87,5', '88'], '0,4 · 65 = 26 olduğundan finalin katkısı 80 − 26 = 54 olmalıdır; 54 / 0,6 = 90.'),
  ('20 ailede çocuk sayısı sorulmuş: 3 ailede 0, 7 ailede 1, 6 ailede 2, 4 ailede 3 çocuk vardır. Aile başına ortalama çocuk sayısı kaçtır?', '1,55', ['1,5', '1,625', '1,45'], 'Toplam çocuk 0·3 + 1·7 + 2·6 + 3·4 = 31\'dir; 31 / 20 = 1,55.'),
  ('Bir çocuk kulübünde 20 öğrencinin haftalık kitap okuma saatleri kaydedilmiştir: 5 saat (2 kişi), 6 saat (5 kişi), 7 saat (8 kişi), 8 saat (3 kişi), 9 saat (2 kişi). Ortalama okuma süresi kaç saattir?', '6,9', ['7', '7,15', '6,8'], 'Toplam 10 + 30 + 56 + 24 + 18 = 138 saattir; 138 / 20 = 6,9 saat.'),
  ('Medyan için aşağıdaki ifadelerden hangisi doğrudur?', 'Sıralanmış verinin en az yarısı medyana eşit ya da ondan küçüktür', ['Değerlerin toplamının gözlem sayısına bölümüdür', 'Her veri setinde veri değerlerinden biridir', 'Aşırı değerlerden aritmetik ortalamaya göre çok daha fazla etkilenir'], 'Medyan sıralı veriyi iki eşit parçaya böler. Çift sayıda gözlemde veri değerlerinden biri olmayabilir ve aykırı değerlere karşı ortalamadan daha dirençlidir.'),
  ('Bir apartmandaki 20 dairede yaşayan kişi sayıları şöyledir: 4 dairede 1, 9 dairede 2, 5 dairede 3, 2 dairede 4 kişi. Daire başına kişi sayısının medyanı kaçtır?', '2', ['2,5', '3', '2,25'], 'Sıralı veride 10. ve 11. değerler gerekir. İlk 4 değer 1, sonraki 9 değer (5.–13.) 2\'dir; dolayısıyla medyan 2\'dir.'),
  ('Bir ankette memnuniyet \'çok kötü, kötü, orta, iyi, çok iyi\' biçiminde ölçülmüştür. Aşağıdakilerden hangisi bu sıralı veri için anlamlı olup sınıflayıcı veri için anlamlı değildir?', 'Medyan', ['Mod', 'Frekans', 'Kategori sayısı'], 'Sıralı (ordinal) veride kategoriler sıralanabildiğinden ortadaki yanıt, yani medyan bulunabilir. Mod ve frekans her iki veri türü için de kullanılabilir.'),
  ('Hangi merkezî eğilim ölçüsü her türlü ölçek düzeyinde (sınıflayıcı, sıralı, aralıklı, oranlı) kullanılabilir?', 'Mod', ['Aritmetik ortalama', 'Medyan', 'Harmonik ortalama'], 'Mod yalnız frekans saymayı gerektirdiğinden sınıflayıcı veriden oranlı veriye kadar her düzeyde tanımlıdır. Medyan sıralama, ortalama ise toplama gerektirir.'),
  ('Beş çalışanın günlük kazançları (dolar) 30, 32, 35, 33, 31\'dir. 35 kazanan çalışanın kazancı yanlışlıkla 135 yazılırsa ortalama ve medyan nasıl değişir?', 'Ortalama 20 artar, medyan değişmez', ['Ortalama da medyan da 20 artar', 'Ortalama değişmez, medyan 100 artar', 'Ortalama 100 artar, medyan 1 artar'], 'Toplam 100 arttığından ortalama 100 / 5 = 20 artar (32,2\'den 52,2\'ye). Sıralamada ortadaki değer yine 32 olduğundan medyan değişmez.'),
  ('Bir mahalledeki evlerin çoğu orta fiyatlıyken birkaç lüks villa da bulunuyor. Ev fiyatlarının dağılımı için hangi ilişki beklenir?', 'Ortalama, medyandan büyüktür', ['Ortalama, medyandan küçüktür', 'Ortalama ile medyan eşittir', 'Mod, hem ortalamadan hem medyandan büyüktür'], 'Birkaç çok yüksek fiyat dağılımı sağa çarpık yapar ve ortalamayı yukarı çeker; medyan ise orta konumda kalır.'),
  ('Kolay bir sınavda öğrencilerin çoğu yüksek puan almış, az sayıda öğrenci ise çok düşük puan almıştır. Bu sola çarpık dağılımda en olası sıralama hangisidir?', 'Ortalama < Medyan < Mod', ['Mod < Medyan < Ortalama', 'Medyan < Ortalama < Mod', 'Üçü de birbirine eşittir'], 'Sola çarpık dağılımda düşük uçtaki az sayıdaki değer ortalamayı aşağı çeker; tepe noktası (mod) yüksek puanlardadır, medyan ikisinin arasında kalır.'),
  ('2, 3, 3, 4, 5, 6, 30 verisi için ortalama, medyan ve modun doğru sıralaması hangisidir?', 'Mod < Medyan < Ortalama', ['Ortalama < Medyan < Mod', 'Medyan < Mod < Ortalama', 'Mod < Ortalama < Medyan'], 'Mod 3, medyan 4, ortalama 53 / 7 ≈ 7,57\'dir. 30 değeri ortalamayı yukarı çeker.'),
  ('Bir taksi şirketi yakıt bütçesi için bir aylık toplam yolculuk mesafesini tahmin etmek istiyor. Günlük mesafelerin hangi ölçüsü bu amaca en uygundur?', 'Aritmetik ortalama', ['Medyan', 'Mod', 'Çeyrekler açıklığının yarısı'], 'Toplamı tahmin etmek için ortalama doğrudan işe yarar: toplam = ortalama × gün sayısı. Medyan ve mod bu çarpım ilişkisini sağlamaz.'),
  ('Bir veri setindeki her değer 3 ile çarpılırsa varyans nasıl değişir?', '9 katına çıkar', ['√3 katına çıkar', 'Değişmez', '3 artar'], 'Var(aX) = a²·Var(X) olduğundan 3 ile çarpma varyansı 3² = 9 katına çıkarır; standart sapma ise 3 katına çıkar.'),
  ('Bir şehirde bir ay boyunca ölçülen günlük sıcaklıkların ortalaması 20 °C, standart sapması 5 °C\'dir. F = 1,8C + 32 dönüşümüyle Fahrenheit\'a çevrilince ortalama ve standart sapma ne olur?', '68 °F ve 9 °F', ['68 °F ve 41 °F', '36 °F ve 9 °F', '68 °F ve 5 °F'], 'Ortalama 1,8 · 20 + 32 = 68 °F olur. Standart sapmaya yalnız çarpan etki eder: 1,8 · 5 = 9 °F; +32 yayılımı değiştirmez.'),
  ('Medyanı 25 olan bir verideki her değer −2 ile çarpılıyor. Yeni verinin medyanı kaçtır?', '−50', ['50', '−25', '23'], 'Negatif bir sayıyla çarpma sıralamayı tersine çevirir ama ortadaki konum yine ortada kalır; yeni medyan −2 · 25 = −50 olur.'),
  ('Standart sapması 6 olan bir verideki her değer −2 ile çarpılıp sonuca 7 ekleniyor. Yeni standart sapma kaçtır?', '12', ['−12', '5', '19'], 'Y = aX + b için σ_Y = |a|·σ_X\'tir. |−2| · 6 = 12 olur; standart sapma negatif olamaz ve sabit ekleme onu etkilemez.'),
  ('Bir sınıfın boy ölçümleri metre yerine santimetre olarak kaydedilirse varyans nasıl değişir?', '10 000 katına çıkar', ['100 katına çıkar', 'Değişmez', '1 000 000 katına çıkar'], 'Santimetreye çevirmek her değeri 100 ile çarpmaktır. Varyans çarpanın karesiyle değişir: 100² = 10 000.'),
  ('Bir veri setinin her değerine aynı sabit eklenirse aşağıdaki ölçülerden hangisi değişir?', 'Mod', ['Açıklık', 'Çeyrekler açıklığı', 'Standart sapma'], 'Sabit ekleme bütün konum ölçülerini (ortalama, medyan, mod) kaydırır; açıklık, çeyrekler açıklığı ve standart sapma gibi yayılım ölçüleri değişmez.'),
  ('Elemanları 5, 9, x, 14 ve 20 olan bir verinin açıklığı 25\'tir. x tam sayısı 5\'ten küçükse x kaçtır?', '−5', ['0', '45', '−20'], 'x en küçük değer olacağından 20 − x = 25 ve x = −5 bulunur.'),
  ('3, 5, 7, 8, 12, 13, 14, 18, 21 verisinin birinci çeyreği (Q1) kaçtır? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', '6', ['5', '7', '6,5'], 'Medyan 12\'dir. Alt yarı 3, 5, 7, 8 olup medyanı (5 + 7) / 2 = 6\'dır.'),
  ('Bir koşu kulübündeki 10 üyenin yaşları 22, 25, 27, 30, 31, 35, 38, 40, 44, 47\'dir. Üçüncü çeyrek (Q3) kaç yaştır? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', '40', ['38', '41', '42,5'], '10 gözlemde alt yarı ilk 5, üst yarı son 5 değerdir. Üst yarı 35, 38, 40, 44, 47 olup medyanı 40\'tır.'),
  ('Sekiz bitkinin bir haftada uzadığı miktarlar (mm) 4, 6, 9, 11, 15, 17, 20, 24\'tür. Bu verinin çeyrekler açıklığı (IQR) kaçtır? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', '11', ['20', '13', '10,5'], 'Alt yarı 4, 6, 9, 11 olduğundan Q1 = 7,5; üst yarı 15, 17, 20, 24 olduğundan Q3 = 18,5\'tir. IQR = 18,5 − 7,5 = 11.'),
  ('Bir verinin beş sayı özeti 10, 18, 25, 31, 70 olarak verilmiştir. Bu bilgiye göre aşağıdakilerden hangisi doğrudur?', 'Gözlemlerin yaklaşık yarısı 18 ile 31 arasındadır', ['Ortalama kesinlikle 25\'tir', 'Açıklık 13\'tür', 'Gözlemlerin yaklaşık dörtte biri 31\'den küçüktür'], 'Q1 ile Q3 arası verinin ortadaki yaklaşık %50\'sini kapsar. Ortalama bu özetten bulunamaz; açıklık 70 − 10 = 60\'tır.'),
  ('Çeyrekler açıklığı neden açıklığa göre aykırı değerlere daha dirençli bir yayılım ölçüsüdür?', 'Verinin ortadaki %50\'sine dayanıp uçları dışarıda bırakır', ['Tüm gözlemlerin ortalamadan uzaklığını eşit ağırlıkla hesaba katar', 'Her zaman açıklıktan büyük bir sayı verir', 'Yalnız en büyük ve en küçük değeri kullanır'], 'IQR = Q3 − Q1 yalnız orta yarıyı ölçer; en uçtaki değerler ne kadar büyük ya da küçük olursa olsun Q1 ve Q3\'ü çok az etkiler.'),
  ('Q1\'i 40 ve Q3\'ü 60 olan bir veride 1,5 × IQR kuralına göre aşağıdaki değerlerden hangisi aykırı sayılır?', '8', ['12', '88', '64'], 'IQR = 20, sınırlar 40 − 30 = 10 ve 60 + 30 = 90\'dır. Yalnız 8 bu aralığın dışında kalır.'),
  ('Bir fırında 12 gün boyunca atılan bayat ekmek sayıları 7, 9, 10, 10, 12, 13, 15, 16, 18, 19, 40, 2\'dir. Çeyrekler açıklığı kaçtır? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', '7,5', ['38', '8', '6,5'], 'Sıralı veri 2, 7, 9, 10, 10, 12 | 13, 15, 16, 18, 19, 40\'tır. Q1 = (9 + 10) / 2 = 9,5; Q3 = (16 + 18) / 2 = 17; IQR = 7,5. 38 ise açıklıktır.'),
  ('Bir öğrencinin beş gün boyunca ders çalıştığı süreler (saat) 5, 7, 7, 9 ve 12\'dir. Bu verinin ortalama mutlak sapması kaçtır?', '2', ['2,4', '1,6', '3'], 'Ortalama 8\'dir. Mutlak sapmalar 3, 1, 1, 1, 4 olup toplamı 10\'dur; 10 / 5 = 2.'),
  ('Bir bisikletçinin beş antrenmanda kat ettiği mesafeler 10, 12, 15, 18 ve 20 km\'dir. Ortalamadan mutlak sapmaların ortalaması kaç km\'dir?', '3,2', ['3', '4,12', '2,8'], 'Ortalama 15 km\'dir. |−5| + |−3| + 0 + 3 + 5 = 16 ve 16 / 5 = 3,2 km bulunur.'),
  ('2, 4, 6, 8, 10 değerlerinden oluşan anakütlenin varyansı kaçtır?', '8', ['10', '6', '4'], 'Ortalama 6\'dır. Kare sapmalar 16, 4, 0, 4, 16 olup toplamı 40\'tır; anakütle varyansı 40 / 5 = 8.'),
  ('Bir fabrikadan rastgele seçilen beş ürünün ağırlık sapmaları (gram) 2, 4, 6, 8 ve 10\'dur. Bu örneklemin varyansı (n − 1 bölücüsüyle) kaçtır?', '10', ['8', '12,5', '6'], 'Ortalama 6, kare sapmalar toplamı 40\'tır. Örneklem varyansı 40 / (5 − 1) = 10 olur.'),
  ('Beş kavanozun dolum miktarları (gram) 48, 52, 50, 46 ve 54\'tür. Bu beş kavanoz anakütle kabul edilirse standart sapma kaç gramdır?', '2√2', ['√10', '4', '2'], 'Ortalama 50\'dir. Kare sapmalar 4, 4, 0, 16, 16 toplamı 40\'tır. Varyans 40 / 5 = 8, standart sapma √8 = 2√2 ≈ 2,83 gram.'),
  ('2, 4, 4, 4, 5, 5, 7, 9 değerlerinin anakütle standart sapması kaçtır?', '2', ['4', '1,5', '2,5'], 'Ortalama 40 / 8 = 5\'tir. Kare sapmalar 9, 1, 1, 1, 0, 0, 4, 16 toplamı 32\'dir. Varyans 32 / 8 = 4, standart sapma 2 bulunur.'),
  ('Standart sapmanın varyansa göre yorumlanmasının daha kolay olmasının nedeni nedir?', 'Verinin kendi ölçü birimiyle ifade edilir', ['Her zaman varyanstan küçüktür', 'Aykırı değerlerden varyansın aksine hiç etkilenmez', 'Hesaplanması için ortalama gerekmez'], 'Varyans birimin karesiyle (örneğin cm²) ifade edilir. Karekök alınarak elde edilen standart sapma ise verinin birimiyle (cm) aynıdır.'),
  ('Bir öğretmen üç öğrencinin hata sayılarını (1, 5 ve 9) bir örneklem olarak ele alıyor. Örneklem standart sapması kaçtır?', '4', ['√(32/3)', '16', '8/3'], 'Ortalama 5, kare sapmalar toplamı 16 + 0 + 16 = 32\'dir. Örneklem varyansı 32 / 2 = 16, standart sapma 4\'tür.'),
  ('Bir fabrikada yedi makinenin saatlik üretimleri 85, 90, 95, 100, 105, 110 ve 115 parçadır. Yedi makine anakütle sayılırsa üretimlerin standart sapması kaç parçadır?', '10', ['5', '100', '10,8'], 'Ortalama 100\'dür. Kare sapmalar 225, 100, 25, 0, 25, 100, 225 toplamı 700\'dür; 700 / 7 = 100 ve √100 = 10. 10,8 örneklem standart sapmasıdır.'),
  ('Bir okçu aynı hedefe 10 atış yapıyor. Okların merkeze uzaklıklarının standart sapması küçükse bu en çok neyi gösterir?', 'Atışların tutarlı olduğunu', ['Bütün okların tam merkeze isabet ettiğini', 'Ortalama uzaklığın sıfır olduğunu', 'Atış sayısının yetersiz olduğunu'], 'Küçük standart sapma uzaklıkların birbirine yakın, yani atışların tutarlı olduğunu gösterir. Okların merkeze ne kadar yakın olduğu ortalamaya bağlıdır.'),
  ('Fil ağırlıkları (ortalama 5000 kg, standart sapma 500 kg) ile fare ağırlıklarının (ortalama 20 g, standart sapma 4 g) göreli değişkenliği karşılaştırılmak isteniyor. Hangi sonuç doğrudur?', 'Fare ağırlıklarının göreli değişkenliği daha büyüktür', ['Fil ağırlıklarının göreli değişkenliği daha büyüktür', 'İkisinin göreli değişkenliği eşittir', 'Birimler farklı olduğundan iki veri karşılaştırılmaya uygun değildir'], 'Değişim katsayıları filde 500 / 5000 = %10, farede 4 / 20 = %20\'dir. DK birimsiz olduğu için farklı ölçeklerdeki verilerin karşılaştırılmasına uygundur.'),
  ('Değişim katsayısı hangi tür verilerin karşılaştırılmasında özellikle yararlıdır?', 'Ortalamaları ya da birimleri çok farklı veri setlerinin', ['Yalnız kategorik verilerin', 'Ortalaması sıfır olan verilerin', 'Gözlem sayıları birbirine eşit olan iki ayrı veri setinin'], 'DK standart sapmayı ortalamaya oranlayarak birimden bağımsız bir göreli yayılım ölçüsü verir. Ortalama sıfıra yakınsa anlamsızlaşır.'),
  ('A hissesinin günlük getirileri ortalama 2, standart sapma 1; B hissesininki ortalama 6, standart sapma 2 birimdir. Getiri birimi başına riski (değişim katsayısı) daha düşük olan hisse hangisidir?', 'B', ['A', 'İkisinin oranı eşittir', 'Bu bilgilerle karşılaştırılamaz'], 'DK, A için 1 / 2 = 0,50; B için 2 / 6 ≈ 0,33\'tür. B\'nin standart sapması daha büyük olsa da göreli riski daha düşüktür.'),
  ('Bir koşu yarışında bitiş sürelerinin ortalaması 72 dakika, standart sapması 12 dakikadır. z-puanı −0,5 olan bir koşucu yarışı kaç dakikada bitirmiştir?', '66', ['78', '71,5', '60'], 'x = 72 + (−0,5) · 12 = 72 − 6 = 66 dakika.'),
  ('Ece fizikten 82 (sınıf ortalaması 70, standart sapma 8), kimyadan 74 (ortalama 60, standart sapma 5) almıştır. Sınıfına göre hangi derste daha başarılıdır?', 'Kimyada, çünkü z-puanı daha yüksektir', ['Fizikte, çünkü ham puanı daha yüksektir', 'Fizikte, çünkü ortalamadan farkı 12\'dir', 'İki derste eşit başarılıdır'], 'Fizikte z = 12 / 8 = 1,5; kimyada z = 14 / 5 = 2,8\'dir. Göreli konumda kimya puanı daha üstündür.'),
  ('Bir veri setindeki tüm değerler z-puanlarına dönüştürülürse yeni verinin ortalaması ve standart sapması ne olur?', 'Ortalama 0, standart sapma 1', ['Ortalama 1, standart sapma 0', 'Ortalama 0, standart sapma 0', 'Ortalama ve standart sapma değişmez'], 'z = (x − x̄) / σ dönüşümü önce ortalamayı çıkarıp veriyi 0\'a merkezler, sonra σ\'ya bölerek yayılımı 1\'e ölçekler.'),
  ('Çebişev eşitsizliğine göre, dağılımın biçimi ne olursa olsun, verilerin en az yüzde kaçı ortalamanın 2 standart sapma yakınında bulunur?', '%75', ['%95', '%50', '%68,3'], 'Çebişev\'e göre k > 1 için en az 1 − 1/k² oranı ortalamadan k standart sapma içindedir: 1 − 1/4 = 0,75. %95 yalnız normal dağılım için geçerli yaklaşık bir değerdir.'),
  ('2, 8 ve 32 sayılarının geometrik ortalaması kaçtır?', '8', ['14', '16', '10,5'], 'Çarpım 2 · 8 · 32 = 512\'dir; küpkökü ∛512 = 8 bulunur. 14 aritmetik ortalamadır.'),
  ('Bir hisse senedinin değeri bir yıl %50 artıp sonraki yıl %50 azalmıştır. İki yıl sonundaki durum için hangisi doğrudur?', 'Başlangıç değerinin %75\'ine düşmüştür', ['Başlangıç değerine geri dönmüştür', 'Başlangıç değerinin %125\'ine çıkmıştır', 'Başlangıç değerinin %50\'sine düşmüştür'], 'Değer 1,5 · 0,5 = 0,75 katına iner. Yüzdelerin aritmetik ortalaması (%0) gerçek ortalama değişimi göstermez; geometrik ortalama √0,75 ≈ 0,866\'dır.'),
  ('Geometrik ortalamanın tanımlı ve anlamlı olması için verilerde hangi koşul aranır?', 'Tüm değerlerin pozitif olması', ['Değerlerin tam sayı olması', 'Değerlerin ardışık olması', 'Gözlem sayısının ikiye tam bölünebilmesi'], 'Geometrik ortalama değerlerin çarpımının n. dereceden köküdür. Sıfır ya da negatif değerler bu hesabı anlamsız kılar; bu yüzden pozitif veriler gerekir.'),
  ('Bir sürücü 120 km\'lik yolu gidişte saatte 60 km, dönüşte saatte 40 km hızla katediyor. Bütün yolculuğun ortalama hızı saatte kaç km\'dir?', '48', ['50', '45', '52,5'], 'Gidiş 2 saat, dönüş 3 saat sürer; toplam 240 km / 5 saat = 48 km/sa. Bu, 60 ve 40\'ın harmonik ortalamasıdır.'),
  ('Eşit mesafeler farklı hızlarla katedildiğinde ortalama hız neden hızların aritmetik ortalaması değildir?', 'Düşük hızla daha uzun süre yol alındığı için', ['Hızlar negatif olabileceği için', 'Hızların ölçü birimleri birbirinden farklı olduğu için', 'Yüksek hız daha uzun sürdüğü için'], 'Eşit mesafelerde yavaş bölüm daha çok zaman alır ve ortalamaya daha fazla katılır. Bu durumda doğru ortalama harmonik ortalamadır.'),
  ('2, 3 ve 6 sayılarının harmonik ortalaması kaçtır?', '3', ['3,67', '3,30', '2,5'], 'Terslerin ortalaması (1/2 + 1/3 + 1/6) / 3 = 1 / 3\'tür. Harmonik ortalama bunun tersidir: 3.'),
  ('Pozitif sayılardan oluşan ve değerleri birbirinden farklı bir veri için aritmetik (A), geometrik (G) ve harmonik (H) ortalamalar arasındaki sıralama hangisidir?', 'H < G < A', ['A < G < H', 'G < H < A', 'H < A < G'], 'Pozitif sayılarda her zaman H ≤ G ≤ A\'dır; eşitlik yalnız bütün değerler eşitse sağlanır.'),
  ('Bir sınıfta 10 öğrencinin okuduğu kitap sayıları 2, 5, 6, 7, 8, 9, 10, 11, 12, 40\'tır. En küçük ve en büyük birer değer atılarak hesaplanan %10 kırpılmış ortalama kaçtır?', '8,5', ['11', '8', '9,25'], '2 ve 40 atılınca kalan sekiz değerin toplamı 68\'dir; 68 / 8 = 8,5. Kırpılmamış ortalama ise 110 / 10 = 11\'dir.'),
  ('Bir jimnastik yarışmasında altı hakemin verdiği puanlar 9,1; 9,3; 9,4; 9,6; 9,8; 9,9\'dur. En yüksek ve en düşük puan atılıp kalanların ortalaması alınırsa sporcunun puanı ne olur?', '9,525', ['9,5', '9,55', '9,4833'], '9,1 ve 9,9 atılır. Kalan 9,3 + 9,4 + 9,6 + 9,8 = 38,1 olup 38,1 / 4 = 9,525\'tir.'),
  ('Orta değer (midrange) ölçüsünün en büyük zayıflığı nedir?', 'Aykırı değerlere karşı çok duyarlıdır', ['Her zaman bir veri değeri olmak zorundadır', 'Her zaman aritmetik ortalamadan büyük bir değer verir', 'Gözlem sayısı tek olduğunda tanımsız olur'], 'Orta değer yalnız en küçük ve en büyük değere dayanır; tek bir aşırı değer onu büyük ölçüde kaydırır.'),
  ('Bir sınavda tüm adayların puanına 10 puan eklenirse bir adayın yüzdelik sırası nasıl değişir?', 'Değişmez', ['10 artar', 'Yüzde 10 artar', '100\'e yükselir'], 'Herkese aynı miktar eklenince adayların sıralaması korunur; adayın altında kalanların oranı aynı olduğundan yüzdelik sırası değişmez.'),
  ('Bir okulda 60 öğrencinin ortalaması 55\'tir. Bunlardan kız öğrencilerin sayısı 20 ve ortalaması 70 ise erkek öğrencilerin ortalaması kaçtır?', '47,5', ['40', '45', '50'], 'Toplam puan 60 · 55 = 3300, kızların toplamı 20 · 70 = 1400\'dür. Erkeklerin toplamı 1900 olup 1900 / 40 = 47,5 bulunur.'),
  ('Bir c sayısı için Σ(xᵢ − c)² toplamını en küçük yapan c değeri hangisidir?', 'Aritmetik ortalama', ['Medyan', 'Mod', 'Orta değer'], 'Kare sapmalar toplamı c = x̄ iken en küçüktür (en küçük kareler özelliği). Mutlak sapmalar toplamını ise medyan en küçükler.'),
  ('10 gözlemli bir veri için Σx = 50 ve Σx² = 290 olarak verilmiştir. Anakütle varyansı kaçtır?', '4', ['29', '24', '2'], 'Varyans = Σx² / n − x̄² = 29 − 5² = 4\'tür.'),
  ('Σ(xᵢ − x̄)² = Σxᵢ² − n·x̄² eşitliğinin pratik yararı nedir?', 'Sapmaları tek tek hesaplamadan varyansı bulmayı sağlar', ['Ortalamayı medyana dönüştürür', 'Aykırı değerleri otomatik olarak ayıklar', 'Standart sapmanın negatif çıkmasını her durumda engelleyerek düzeltir'], 'Bu özdeşlik sayesinde yalnız değerlerin toplamı ve kareleri toplamı bilinerek kare sapmalar toplamı elde edilir.'),
  ('Ortalaması 10 ve anakütle standart sapması 3 olan iki sayı hangileridir?', '7 ve 13', ['4 ve 16', '8 ve 12', '1 ve 19'], 'İki sayı için standart sapma, sayıların ortalamadan uzaklığına eşittir. 10 ± 3 → 7 ve 13 bulunur.'),
  ('Bir veri setinin varyansı ve standart sapması eşit ve sıfırdan farklıdır. Standart sapma kaçtır?', '1', ['0,5', '2', 'Bulunamaz'], 'σ² = σ ve σ ≠ 0 ise σ = 1\'dir.'),
  ('Bir veri setindeki bütün gözlemler aynı oranda (ör. %10) artırılırsa standart sapma nasıl değişir?', '%10 artar', ['Değişmez', '%21 artar', '10 birim artar'], 'Yüzde 10 artış her değeri 1,1 ile çarpmaktır; standart sapma da 1,1 katına çıkar. Varyans ise 1,21 katına çıkar.'),
  ('Aşağıdaki yayılım ölçülerinden hangisi aykırı değerlere karşı en dirençlidir?', 'Medyan mutlak sapma', ['Standart sapma', 'Açıklık', 'Varyans'], 'MAD, medyan üzerine kurulu olduğundan uç değerlerden çok az etkilenir. Açıklık, varyans ve standart sapma ise uç değerlere çok duyarlıdır.'),
  ('Ardışık altı tam sayının toplamı 147\'dir. Bu sayıların medyanı kaçtır?', '24,5', ['24', '25', '23,5'], 'Ortalama 147 / 6 = 24,5\'tir. Eşit aralıklı verilerde medyan ortalamaya eşittir; sayılar 22–27 arasıdır ve medyan (24 + 25) / 2 = 24,5.'),
  ('n sayının ortalaması 12\'dir. Bu sayılara 30 eklenince ortalama 14\'e çıkıyor. n kaçtır?', '8', ['9', '7', '6'], '12n + 30 = 14(n + 1) denkleminden 2n = 16 ve n = 8 bulunur.'),
  ('Ortalaması 20 olan sekiz sayıdan biri çıkarılınca kalanların ortalaması 19 oluyor. Çıkarılan sayı kaçtır?', '27', ['21', '1', '20,5'], 'İlk toplam 160, yeni toplam 7 · 19 = 133\'tür. Çıkarılan sayı 160 − 133 = 27\'dir.'),
  ('25 öğrencinin boy ortalaması 158 cm\'dir. Öğrencilerle birlikte 184 cm boyundaki beden eğitimi öğretmeni de ölçülürse 26 kişinin boy ortalaması kaç cm olur?', '159', ['171', '158,5', '160'], 'Öğrencilerin toplam boyu 3950 cm\'dir. 3950 + 184 = 4134 ve 4134 / 26 = 159 cm bulunur.'),
  ('Bir öğrenci hafta içi beş gün günde ortalama 8 saat, hafta sonu iki gün ise günde ortalama 1 saat ders çalışıyor. Haftanın bir gününe düşen ortalama çalışma süresi kaç saattir?', '6', ['4,5', '7', '5,5'], 'Haftalık toplam 5 · 8 + 2 · 1 = 42 saattir; 42 / 7 = 6 saat. Grup ortalamalarının düz ortalaması (4,5) gün sayılarını hesaba katmaz.'),
  ('Bir veri setinin aritmetik ortalaması için aşağıdakilerden hangisi her zaman doğrudur?', 'En küçük ve en büyük değer arasında kalır', ['Medyandan büyüktür', 'Her zaman veri değerlerinden birine eşittir', 'Moddan küçüktür'], 'Ortalama değerlerin dengelendiği noktadır; bütün değerlerden küçük ya da bütün değerlerden büyük olamaz. Medyan ve modla ilişkisi dağılıma bağlıdır.'),
  ('Ortalaması sıfırdan farklı bir veri setinin her elemanı bu ortalamaya bölünürse yeni verinin ortalaması kaç olur?', '1', ['0', 'Ortalamanın karesi', 'Gözlem sayısı kadar'], 'Her değer x̄\'e bölündüğünde yeni ortalama x̄ / x̄ = 1 olur.'),
  ('Bir sınıfta öğrencilerin yarısı sınavdan 40, diğer yarısı 80 almıştır. Sınıf ortalaması ve medyan hakkında hangisi doğrudur?', 'İkisi de 60\'tır', ['Ortalama 60, medyan 40\'tır', 'Ortalama 60, medyan 80\'dir', 'İkisi de 40\'tır'], 'Ortalama (40 + 80) / 2 = 60\'tır. Çift sayıda gözlemde ortadaki iki değer 40 ve 80 olduğundan medyan da 60\'tır; ancak 60 alan öğrenci yoktur.'),
  ('Bir pazarlamacı \'müşterilerimizin ortalama yaşı 35\' diyor; oysa müşterilerin yarısı 20, yarısı 50 yaşındadır. Bu durum hangi uyarıyı haklı çıkarır?', 'Ortalama, tek başına tipik bir bireyi temsil etmeyebilir', ['Ortalama yanlış hesaplanmıştır', 'Medyan bu veride tanımsızdır', 'Bu veride standart sapmanın sıfır olduğu kesin olarak söylenebilir'], 'Ortalama doğru hesaplanmış olsa bile iki kümeli bir veride hiçbir müşteri 35 yaşında değildir. Yayılım ölçüsü ve dağılım biçimi de raporlanmalıdır.'),
  ('Beş sayının ortalaması 16\'dır. Sayılardan biri 8 artırılır, bir başkası 3 azaltılırsa yeni ortalama kaç olur?', '17', ['21', '16,5', '19'], 'Toplam 80\'dir ve net olarak 8 − 3 = 5 artar. 85 / 5 = 17 bulunur.'),
  ('Bir yarışmada yedi öğrencinin çözdüğü soru sayıları 11, 15, 18, 20, 23, 27, 30\'dur. Sonradan katılan iki öğrenci 35 ve 40 soru çözmüştür. Dokuz öğrencinin çözdüğü soru sayılarının medyanı nedir?', '23', ['20', '21,5', '27'], 'Dokuz değerli yeni sıralı veri 11, 15, 18, 20, 23, 27, 30, 35, 40\'tır; beşinci değer 23\'tür.'),
  ('Bir ankete katılan 50 kişinin yanıtları şöyledir: \'çok kötü\' 5, \'kötü\' 8, \'orta\' 15, \'iyi\' 17, \'çok iyi\' 5 kişi. Yanıtların medyanı hangisidir?', 'Orta', ['İyi', 'Kötü', 'Çok iyi'], 'Medyan 25. ve 26. yanıtlardır. Birikimli sayılar 5, 13, 28 olduğundan 14.–28. yanıtlar \'orta\'dır; medyan \'orta\' olur. Mod ise \'iyi\'dir.'),
  ('3, 5, a, 9, b verisi küçükten büyüğe sıralıdır ve ortalaması 7, medyanı 8\'dir. b kaçtır?', '10', ['9', '11', '12'], 'Beş değerin ortadakisi a olduğundan a = 8\'dir. Toplam 35 olmalıdır: 3 + 5 + 8 + 9 + b = 35 ve b = 10.'),
  ('Bir sınıfta 31 öğrencinin boyları sıralanmıştır. Sınıfa en kısa öğrenciden daha kısa bir öğrenci ve en uzun öğrenciden daha uzun bir öğrenci katılırsa medyan nasıl değişir?', 'Değişmez', ['Artar', 'Azalır', 'İki yeni değerin ortalaması olur'], 'Her iki uca birer değer eklenince ortadaki konum değişmez; 16. öğrenci 33 kişilik sırada 17. konuma kayar ve yine ortadadır.'),
  ('2, 3, x, 5, 7 verisinin tek modu 5 ise x kaçtır?', '5', ['2', '3', '7'], 'x, 2, 3 ya da 7 olsaydı o değer iki kez geçer ve mod o olurdu. Modun yalnız 5 olması için x = 5 olmalıdır.'),
  ('Bir futbol takımındaki oyuncuların forma numaralarının ortalaması 12,4 bulunmuştur. Bu değer için en doğru yorum hangisidir?', 'Anlamsızdır; forma numaraları yalnız etiket görevi görür', ['Takımın tipik oyuncusunu temsil eder', 'Oyuncuların ortalama deneyimini gösterir', 'Forma numaralarının modu da 12,4\'tür'], 'Forma numaraları sayı biçiminde olsa da sınıflayıcı etiketlerdir; aritmetik işlemler anlamlı bir bilgi vermez.'),
  ('Aşağıdakilerden hangisi her sayısal veri setinde tek bir değer olarak mutlaka vardır?', 'Aritmetik ortalama', ['Mod', 'Tekrar eden değer', 'Aykırı değer'], 'Sayısal bir veride toplam ve gözlem sayısı her zaman tanımlı olduğundan ortalama tektir. Mod hiç olmayabilir ya da birden çok olabilir.'),
  ('Bir giyim mağazası müşterilerin tişört bedenlerini (S, M, L, XL) kaydediyor. Hangi istatistiklerin ikisi de bu veri için anlamlıdır?', 'Mod ve medyan', ['Ortalama ve standart sapma', 'Ortalama ve medyan', 'Varyans ve mod'], 'Beden sıralı bir değişkendir: en sık beden (mod) ve ortadaki beden (medyan) belirlenebilir; ortalama ve varyans için sayısal uzaklık gerekir.'),
  ('Bir kasiyerin beş gün boyunca verdiği hatalı para üstü sayıları 4, 8, 6, 5, 7\'dir. Beş gün anakütle kabul edilirse varyans kaçtır?', '2', ['2,5', '1,4', '10'], 'Ortalama 6\'dır. Kare sapmalar 4, 4, 0, 1, 1 toplamı 10\'dur; 10 / 5 = 2. 2,5 örneklem varyansıdır.'),
  ('Bir öğrenci rastgele seçtiği dört günde 12, 14, 16 ve 18 sayfa kitap okumuştur. Bu örneklemin varyansı (n − 1 ile) kaçtır?', '20/3', ['5', '10/3', '4'], 'Ortalama 15, kare sapmalar 9 + 1 + 1 + 9 = 20\'dir. Örneklem varyansı 20 / 3 ≈ 6,67 olur; 5 ise n\'ye bölünmüş değerdir.'),
  ('Bir ilaç fabrikasında tabletlerin etken madde miktarında ortalama doğru olsa bile standart sapmanın küçük tutulması neden önemlidir?', 'Her tabletin hedef doza yakın olmasını sağlamak için', ['Ortalamayı yükseltmek için', 'Tablet sayısını artırmak için', 'Etken madde miktarının varyansını negatif yapabilmek için'], 'Ortalama doğru olsa bile büyük yayılım bazı tabletlerin çok düşük, bazılarının çok yüksek doz içermesine yol açar. Kalite kontrolde düşük standart sapma tutarlılık demektir.'),
  ('Bir sınavda iki öğrencinin z-puanları 1,2 ve −0,8\'dir. Standart sapma 10 puan ise iki öğrencinin ham puanları arasındaki fark kaçtır?', '20', ['4', '2', '12'], 'Ham puan farkı = (z₁ − z₂) · σ = (1,2 − (−0,8)) · 10 = 2 · 10 = 20 puandır.'),
  ('Ayşe\'nin 100 m koşu süresinin z-puanı −1,5, Mehmet\'in z-puanı 0,5\'tir (sürelerin ortalaması ve standart sapması aynı gruptan hesaplanmıştır). Hangisi daha hızlı koşmuştur?', 'Ayşe, çünkü süresi ortalamanın daha altındadır', ['Mehmet, çünkü z-puanı pozitiftir', 'Mehmet, çünkü süresi ortalamanın üstündedir', 'İkisi eşit hızdadır, çünkü z-puanlarının toplamı sıfıra yakındır'], 'Koşu süresinde küçük değer daha iyidir. Negatif z-puanı ortalamadan kısa süreyi gösterdiğinden Ayşe daha hızlıdır.'),
  ('İki farklı sınavda öğrencilerin performansını karşılaştırmak için ham puanlar yerine z-puanları kullanılmasının nedeni nedir?', 'Sınavların ortalama ve yayılım farkını ortadan kaldırması', ['z-puanlarının her zaman pozitif olması', 'Hesaplamanın medyana dayanması', 'Ham puanların farklı sınavlarda her zaman hatalı hesaplanmış olması'], 'z-puanı her değeri kendi dağılımının ortalaması ve standart sapmasına göre ifade ettiğinden farklı ölçekteki sonuçları ortak bir ölçeğe taşır.'),
  ('Bir koşu grubunda süreler için değişim katsayısı %25, standart sapma 3,5 dakikadır. Ortalama süre kaç dakikadır?', '14', ['8,75', '12,5', '17,5'], 'DK = σ / x̄ olduğundan x̄ = σ / DK = 3,5 / 0,25 = 14 dakikadır.'),
  ('A ilçesinde aylık gelirlerin ortalaması 20 000 TL, standart sapması 5000 TL; B ilçesinde ortalama 40 000 TL, standart sapma 8000 TL\'dir. Göreli gelir eşitsizliği hangi ilçede daha büyüktür?', 'A', ['B', 'İkisinde eşittir', 'Ortalamalar farklı olduğundan karşılaştırılamaz'], 'DK, A\'da 5000 / 20 000 = %25, B\'de 8000 / 40 000 = %20\'dir. Mutlak yayılım B\'de büyük olsa da göreli yayılım A\'da büyüktür.'),
  ('Bir araç bir yolun ilk yarısını saatte 50 km, ikinci yarısını saatte 100 km hızla gidiyor. Bütün yoldaki ortalama hızı saatte yaklaşık kaç km\'dir?', '66,7', ['75', '70', '62,5'], 'Yol 200 km kabul edilirse süreler 2 ve 1 saattir; 200 / 3 ≈ 66,7 km/sa. Bu, 50 ve 100\'ün harmonik ortalamasıdır.'),
  ('Bir kafe iki tedarikçiden 10\'ar kilogram kahve çekirdeği satın alıyor. Kilogram fiyatı birinci tedarikçide 300 TL, ikincide 600 TL\'dir. Kafenin kilogram başına ödediği ortalama fiyat kaç TL\'dir?', '450', ['400', '424', '500'], 'Toplam ödeme 3000 + 6000 = 9000 TL, toplam 20 kg\'dır; 9000 / 20 = 450 TL. Alınan miktar sabit olduğunda fiyatların aritmetik ortalaması uygundur.'),
  ('log₁₀ değerleri 1 ve 3 olan 10 ile 1000 sayılarının geometrik ortalaması kaçtır?', '100', ['505', '500', '200'], 'Geometrik ortalamanın logaritması, logaritmaların aritmetik ortalamasıdır: (1 + 3) / 2 = 2. Bu nedenle GO = 10² = 100\'dür.'),
  ('Bir öğrencinin bir yatırım fonu için \'üç yılda yıllık getiriler %5, %5, %5 olduğuna göre ortalama getiri %5\'tir\' demesi için hangisi doğrudur?', 'Doğrudur; eşit oranlarda aritmetik ve geometrik ortalama aynıdır', ['Yanlıştır; geometrik ortalama %5\'ten küçüktür', 'Yanlıştır; harmonik ortalama kullanılmalıdır', 'Yanlıştır; ortalama getiri %15\'tir'], 'Bütün çarpanlar 1,05 olduğunda geometrik ortalama da 1,05\'tir; değerler eşit olduğundan tüm ortalamalar çakışır.'),
  ('Bir parkta 20 ziyaretçinin kalış süreleri gruplanmıştır: 0–10 dakika 5 kişi, 10–20 dakika 10 kişi, 20–30 dakika 5 kişi. Sınıf orta noktaları kullanılırsa ortalama kalış süresi yaklaşık kaç dakikadır?', '15', ['10', '20', '17,5'], 'Orta noktalar 5, 15, 25\'tir. (5 · 5 + 15 · 10 + 25 · 5) / 20 = 300 / 20 = 15 dakika.'),
  ('Bir sınavda puanlar 40–50 aralığında 4, 50–60 aralığında 6, 60–70 aralığında 10 öğrencidir. Sınıf orta değerleriyle tahmin edilen ortalama puan kaçtır?', '58', ['55', '60', '57,5'], 'Orta değerler 45, 55, 65\'tir. (45 · 4 + 55 · 6 + 65 · 10) / 20 = 1160 / 20 = 58.'),
  ('Gruplanmış bir veride ortalama sınıf orta noktalarıyla hesaplanıyorsa elde edilen değer için hangisi doğrudur?', 'Gerçek ortalamaya ilişkin bir yaklaşık değerdir', ['Gerçek ortalamaya her zaman tam eşittir', 'Her zaman gerçek ortalamadan büyüktür', 'Gerçek ortalamayı değil medyanın kesin değerini her zaman verir'], 'Her sınıftaki gözlemlerin orta noktada toplandığı varsayılır. Gözlemler sınıf içinde farklı dağıldığından sonuç yalnız bir tahmindir.'),
  ('Bir öğrencinin altı sınavının ortalaması 70\'tir. En düşük notu hesaptan çıkarılınca kalan beş sınavın ortalaması 75 oluyor. En düşük notu kaçtır?', '45', ['50', '55', '40'], 'Altı sınavın toplamı 420, beş sınavın toplamı 375\'tir. En düşük not 420 − 375 = 45\'tir.'),
  ('Bir araç 2 saat saatte 60 km, ardından 1 saat saatte 90 km hızla gidiyor. Yolculuğun ortalama hızı saatte kaç km\'dir?', '70', ['75', '72', '66'], 'Toplam yol 120 + 90 = 210 km, toplam süre 3 saattir; 210 / 3 = 70 km/sa. Süreler ağırlık olarak kullanılan bir aritmetik ortalamadır.'),
  ('Sürelerin eşit, mesafelerin farklı olduğu bir yolculukta farklı hızların ortalaması hangi ortalamayla bulunur?', 'Aritmetik ortalama', ['Harmonik ortalama', 'Geometrik ortalama', 'Medyan'], 'Eşit sürelerde toplam yol, hızların toplamıyla orantılıdır; ortalama hız hızların aritmetik ortalamasıdır. Eşit mesafelerde ise harmonik ortalama gerekir.'),
  ('Bir okulda üç şubenin mevcutları 20, 30 ve 50; sınav ortalamaları sırasıyla 60, 70 ve 80\'dir. Okul ortalaması kaçtır?', '73', ['70', '75', '72,5'], '(20 · 60 + 30 · 70 + 50 · 80) / 100 = (1200 + 2100 + 4000) / 100 = 73. Şube ortalamalarının düz ortalaması (70) yanıltıcı olur.'),
  ('Haftalık ders saatleri 4, 3, 2 ve 1 olan dört dersten bir öğrenci sırasıyla 85, 70, 90 ve 60 almıştır. Ders saatleriyle ağırlıklandırılmış ortalaması kaçtır?', '79', ['76,25', '80', '78,5'], 'Ağırlıklı toplam 340 + 210 + 180 + 60 = 790, ağırlıklar toplamı 10\'dur; 790 / 10 = 79.'),
  ('Bir öğrenci üç ödevden 80, 90 ve 70 almıştır. Öğretmen ödevlere sırasıyla 1, 2 ve 1 ağırlık verirse ağırlıklı ortalama, basit ortalamaya göre nasıl değişir?', '2,5 puan yükselir', ['Değişmez', '2,5 puan düşer', '5 puan yükselir'], 'Basit ortalama 80\'dir. Ağırlıklı ortalama (80 + 180 + 70) / 4 = 82,5 olur. En yüksek notun ağırlığı arttığı için ortalama 2,5 puan yükselir.'),
  ('A verisi 0, 5, 5, 5, 10 ve B verisi 0, 0, 5, 10, 10\'dur. İki verinin ortalaması ve açıklığı eşittir. Standart sapmaları için hangisi doğrudur?', 'B\'nin standart sapması daha büyüktür', ['A\'nın standart sapması daha büyüktür', 'Açıklıklar eşit olduğu için standart sapmalar da eşittir', 'İkisinin standart sapması da 5\'tir'], 'B\'de değerlerin çoğu uçlarda toplandığından ortalamadan uzaklıklar daha büyüktür: σ_A = √10 ≈ 3,16, σ_B = √20 ≈ 4,47.'),
  ('4, 6, 8, 10, 32 verisinden 32 çıkarılırsa ortalama ve standart sapma nasıl değişir?', 'İkisi de azalır; standart sapma çok daha belirgin biçimde azalır', ['İkisi de artar', 'Ortalama azalır, standart sapma artar', 'Ortalama değişmez, standart sapma ise yaklaşık dörtte birine düşer'], 'Ortalama 12\'den 7\'ye düşer; standart sapma yaklaşık 10,2\'den 2,24\'e iner. Aykırı değer yayılım ölçüsünü özellikle büyütür.'),
  ('Bir araştırmada çocukların günlük ekran süresi \'3,2 ± 0,8 saat (ortalama ± standart sapma)\' olarak raporlanmıştır. Bu ifadenin doğru okunuşu hangisidir?', 'Ortalama 3,2 saat, standart sapma 0,8 saattir', ['Bütün çocuklar 2,4 ile 4,0 saat arasında ekran başındadır', 'Medyan 3,2 saat, açıklık 0,8 saattir', 'Ortalama 3,2 saat, varyans 0,8 saattir'], '\'±\' gösterimi burada ortalama ile standart sapmayı bildirir; bütün gözlemlerin bu aralıkta olduğu anlamına gelmez.'),
  ('Sağa çarpık ve aykırı değer içeren bir gelir verisini özetlemek için hangi ölçü çifti en uygundur?', 'Medyan ve çeyrekler açıklığı', ['Ortalama ve standart sapma', 'Mod ve açıklık', 'Ortalama ve açıklık'], 'Medyan ve IQR aykırı değerlere ve çarpıklığa karşı dirençlidir; ortalama, standart sapma ve açıklık uç değerlerden çok etkilenir.'),
  ('Simetrik ve aykırı değer içermeyen bir boy verisini özetlemek için en yaygın kullanılan ölçü çifti hangisidir?', 'Ortalama ve standart sapma', ['Mod ve çeyrekler açıklığı', 'Medyan ve açıklık', 'Orta değer ve gözlemlerin varyansı'], 'Simetrik ve uç değersiz verilerde ortalama ve standart sapma bütün gözlemleri kullanır, birbirine uyumludur ve ayrıntılı bilgi verir.'),
  ('İki sınıfın puanları için şu özetler verilmiştir: A sınıfı medyan 70, IQR 8; B sınıfı medyan 70, IQR 25. Buna göre hangisi doğrudur?', 'Ortadaki öğrenciler A sınıfında birbirine daha yakın puanlar almıştır', ['B sınıfı daha başarılıdır', 'A sınıfında en düşük puan daha yüksektir', 'B sınıfının ortalaması, medyanları eşit olduğu için daha büyüktür'], 'Medyanlar eşittir; IQR\'nin küçük olması A sınıfında ortadaki %50\'lik dilimin daha dar bir aralıkta toplandığını gösterir. Diğer yargılar bu bilgilerden çıkmaz.'),
  ('Bir dershanedeki 10 öğrencinin yaşları 15, 18, 20, 21, 23, 25, 26, 28, 31, 45\'tir. 1,5 × IQR kuralına göre 45 yaş için ne söylenebilir? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', 'Aykırı değerdir; üst sınır 40\'tır', ['Aykırı değildir; üst sınır 52\'dir', 'Aykırı değildir; üst sınır 45\'tir', 'Aykırı değerdir; üst sınır 36\'dır'], 'Q1 = 20, Q3 = 28, IQR = 8\'dir. Üst sınır 28 + 12 = 40 olduğundan 45 aykırıdır.'),
  ('Bir kursta 10 öğrencinin bir haftada izlediği belgesel sayıları 3, 4, 4, 5, 5, 5, 6, 6, 7, 20\'dir. 1,5 × IQR kuralına göre hangi değer(ler) aykırıdır? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', 'Yalnız 20', ['7 ve 20', '3 ve 20', 'Aykırı değer yoktur'], 'Q1 = 4, Q3 = 6, IQR = 2\'dir. Sınırlar 4 − 3 = 1 ve 6 + 3 = 9 olur. Yalnız 20 bu aralığın dışındadır.'),
  ('Bir verinin beş sayı özeti 5, 15, 20, 25, 70\'tir. 1,5 × IQR kuralına göre en büyük değer için ne söylenebilir?', 'Aykırı değerdir', ['Aykırı değer değildir', 'Q3 ile aynıdır', 'Medyandan küçüktür'], 'IQR = 25 − 15 = 10, üst sınır 25 + 15 = 40\'tır. 70 bu sınırın üstünde olduğundan aykırıdır.'),
  ('İki ayrı fırının ekmek ağırlıkları için beş sayı özetleri şöyledir: A fırını 240, 248, 250, 252, 260 gram; B fırını 220, 238, 250, 262, 280 gram. Hangi yargı doğrudur?', 'Medyanlar eşit, B fırınının ağırlıkları daha değişkendir', ['A fırınının ekmekleri daha ağırdır', 'B fırınının medyanı daha büyüktür', 'İki fırının çeyrekler açıklığı eşit, açıklıkları farklıdır'], 'Her iki medyan da 250 gramdır. IQR, A\'da 4, B\'de 24 gram olup açıklık da B\'de daha büyüktür; B daha değişkendir.'),
  ('Bir öğrenci \'Q3 = 80 olduğuna göre öğrencilerin dörtte üçü 80 almıştır\' diyor. Bu yorumdaki hata nedir?', 'Q3, öğrencilerin yaklaşık dörtte üçünün 80 ya da altında puan aldığını gösterir', ['Q3 her zaman en yüksek puandır', 'Q3 ortalamanın üç katıdır', 'Q3 yalnız gözlem sayısı tek olduğunda hesaplanabilen bir değerdir ve bu veri için tanımsızdır'], 'Q3 bir eşik değerdir: gözlemlerin yaklaşık %75\'i bu değerin altında ya da ona eşittir. Herkesin 80 aldığı anlamına gelmez.'),
  ('Bir bahçıvan yedi fidanı sulama hortumundan sırasıyla 0, 2, 4, 6, 8, 10 ve 12 cm uzaklığa dikmiştir. Bu uzaklıkların anakütle standart sapması kaç cm\'dir?', '4', ['6', '16', '4,32'], 'Ortalama 6\'dır. Kare sapmalar 36, 16, 4, 0, 4, 16, 36 toplamı 112\'dir; 112 / 7 = 16 ve √16 = 4 cm. 4,32 örneklem standart sapmasıdır.'),
  ('Rastgele seçilen beş müşterinin kasada bekleme süreleri 15, 15, 20, 25 ve 25 saniyedir. Bu örneklemin standart sapması (n − 1 ile) kaç saniyedir?', '5', ['4,47', '25', '20'], 'Ortalama 20\'dir. Kare sapmalar 25, 25, 0, 25, 25 toplamı 100\'dür. Örneklem varyansı 100 / 4 = 25, standart sapma 5 saniyedir.'),
  ('7, 7, 7, 11 verisinin anakütle varyansı kaçtır?', '3', ['4', '1,73', '2'], 'Ortalama 32 / 4 = 8\'dir. Kare sapmalar 1, 1, 1, 9 toplamı 12\'dir; 12 / 4 = 3.'),
  ('Bir sporcu 20 antrenmanda koştuğu mesafeleri (km) kaydetmiştir: Σx = 240 ve Σx² = 4000. Anakütle varyansı kaçtır?', '56', ['200', '144', '7,48'], 'Σx² / n = 200, x̄ = 12\'dir. Varyans 200 − 144 = 56 km² olur.'),
  ('Bir verinin ortalaması 6, karelerinin ortalaması 45\'tir. Anakütle standart sapması kaçtır?', '3', ['9', '√39', '6,7'], 'Varyans = x² ortalaması − (ortalama)² = 45 − 36 = 9; standart sapma √9 = 3\'tür.'),
  ('Gözlem sayısı çok büyüdükçe örneklem varyansı (n − 1 ile) ile n\'ye bölünerek hesaplanan varyans arasındaki fark nasıl değişir?', 'Giderek küçülür', ['Giderek büyür', 'Hep aynı kalır', 'Önce küçülür sonra büyür'], 'İki değerin oranı n / (n − 1)\'dir ve n büyüdükçe 1\'e yaklaşır; fark önemsizleşir.'),
  ('Bir veri setindeki her gözlem, ortalamadan sapması yarıya inecek biçimde ortalamaya yaklaştırılırsa varyans nasıl değişir?', 'Dörtte birine iner', ['Yarıya iner', 'Değişmez', 'Değerler sıkıştığı için iki katına çıkar'], 'Her sapma 0,5 ile çarpılırsa kare sapmalar 0,25 ile çarpılır; varyans dörtte birine, standart sapma yarıya iner.'),
  ('Bir hafta boyunca bir istasyondaki tren gecikmeleri (dakika) 0, 0, 0, 1, 2, 3, 35\'tir. Tipik bir gecikmeyi en iyi hangi değer temsil eder?', 'Medyan olan 1 dakika', ['Ortalama olan 5,9 dakika', 'Açıklık olan 35 dakika', 'Orta değer olan 17,5 dakika'], '35 dakikalık tek gecikme ortalamayı ve orta değeri şişirir. Medyan (1 dakika) günlerin çoğunu daha iyi yansıtır.'),
  ('Bir sağlık ocağında bir gün aşı olan 8 kişinin yaşları 2, 2, 3, 2, 65, 4, 3, 2\'dir. Bu veri için hangi sıralama doğrudur?', 'Mod < Medyan < Ortalama', ['Ortalama < Medyan < Mod', 'Medyan < Mod < Ortalama', 'Mod = Medyan = Ortalama'], 'Mod 2\'dir. Sıralı veri 2, 2, 2, 2, 3, 3, 4, 65 olduğundan medyan 2,5\'tir. Ortalama 83 / 8 ≈ 10,4\'tür.'),
  ('Bir binada 6 dairenin aylık elektrik faturaları (TL) 400, 450, 420, 430, 410, 1590\'dır. Apartman yöneticisi \'ortalama fatura 617 TL\' diyor. Bu ifade için en uygun değerlendirme hangisidir?', 'Hesap doğru ama tek bir yüksek fatura ortalamayı şişirmiştir', ['Hesap yanlıştır; ortalama 425 TL\'dir', 'Hesap doğrudur ve bu değer tipik bir dairenin faturasını iyi temsil eder', 'Hesap yanlıştır; ortalama 1590 TL\'dir'], 'Toplam 3700 TL\'dir ve 3700 / 6 ≈ 616,7 TL\'dir. Ancak beş dairenin faturası 400–450 TL arasındadır; medyan (425 TL) tipik daireyi daha iyi temsil eder.'),
  ('İstatistikte \'standart sapma\' terimini 1894\'te ilk kez kullanan bilim insanı kimdir?', 'Karl Pearson', ['Carl Friedrich Gauss', 'Ronald Fisher', 'Blaise Pascal'], 'Karl Pearson \'standard deviation\' terimini 1894\'teki bir çalışmasında tanıttı; kavramın daha önceki biçimleri farklı adlarla biliniyordu.'),
  ('Kütlesi önemsiz bir cetvelin üzerine, veri değerlerinin bulunduğu noktalara eşit ağırlıklar konuyor. Cetvel hangi noktadan desteklenirse dengede kalır?', 'Aritmetik ortalamada', ['Medyanda', 'Modda', 'En büyük değerde'], 'Ortalama, sapmaların toplamının sıfır olduğu noktadır; fiziksel olarak bu noktalar sisteminin ağırlık merkezidir.'),
  ('Bir merkezî eğilim ölçüsünün verilerdeki her değerden etkilenmesi istenirse aşağıdakilerden hangisi seçilmelidir?', 'Aritmetik ortalama', ['Medyan', 'Mod', 'Orta değer'], 'Ortalama hesabına bütün gözlemler katılır; herhangi bir değer değişirse ortalama da değişir. Medyan, mod ve orta değer yalnız bazı değerlere bağlıdır.'),
  ('a, b, c sayılarının ortalaması 8; a, b, c, d, e sayılarının ortalaması 10\'dur. d ile e\'nin ortalaması kaçtır?', '13', ['2', '12', '9'], 'a + b + c = 24 ve beş sayının toplamı 50\'dir. d + e = 26 olduğundan ortalamaları 13\'tür.'),
  ('30 kişilik bir sınıfın ortalaması 70\'tir. En yüksek puanlı 10 öğrencinin ortalaması 85 ise diğer 20 öğrencinin ortalaması kaçtır?', '62,5', ['55', '65', '60'], 'Sınıf toplamı 2100, ilk 10 kişinin toplamı 850\'dir. Kalan toplam 1250 olup 1250 / 20 = 62,5\'tir.'),
  ('x, x + 2, x + 4 verisinin anakütle varyansı için hangisi doğrudur?', 'x\'ten bağımsız olarak 8/3\'tür', ['x ile birlikte artar', 'x = 0 için 0\'dır', 'x\'ten bağımsız olarak 4\'e eşittir'], 'Sapmalar her zaman −2, 0, 2\'dir; kareleri toplamı 8 olup varyans 8 / 3\'tür. x yalnız konumu kaydırır.'),
  ('İlk 25 pozitif tek sayının (1, 3, 5, …, 49) aritmetik ortalaması kaçtır?', '25', ['24', '26', '24,5'], 'Eşit aralıklı bu dizide ortalama ilk ve son terimin ortalamasıdır: (1 + 49) / 2 = 25.'),
  ('Bir öğrencinin dört yazılı sınavının ortalaması 72\'dir. Beşinci yazılıdan 100 alsa bile ortalaması en fazla kaç olabilir?', '77,6', ['80', '86', '78'], 'Toplam 288 + 100 = 388 olur; 388 / 5 = 77,6. Ortalamayı 80\'e çıkarmak için beşinci sınavdan 112 gerekirdi.'),
  ('Altı sayının ortalaması 9\'dur. Bu sayılardan ikisi çıkarılınca kalanların ortalaması 7 oluyor. Çıkarılan iki sayının ortalaması kaçtır?', '13', ['11', '2', '16'], 'İlk toplam 54, kalan dört sayının toplamı 28\'dir. Çıkarılanların toplamı 26, ortalaması 13\'tür.'),
  ('Bir mağazadaki ürünlerin fiyatları avro cinsinden verilmiştir; ortalama 25 avro, medyan 20 avro, IQR 12 avrodur. Kur 1 avro = 35 TL alınarak TL\'ye çevrilirse IQR kaç TL olur?', '420', ['12', '47', '700'], 'Çeyrekler açıklığı çarpanla aynı oranda değişir: 12 · 35 = 420 TL.'),
  ('Bir veri setinin açıklığı 18\'dir. Her değer −1 ile çarpılırsa yeni açıklık kaç olur?', '18', ['−18', '0', '36'], 'Negatifle çarpma en büyük ile en küçüğün yerini değiştirir ama aralarındaki uzaklık aynı kalır; açıklık negatif olamaz.'),
  ('Bir veri setindeki her değer z-puanına dönüştürülmeden önce ve sonra hangi özellik aynı kalır?', 'Değerlerin sıralaması', ['Ortalama', 'Standart sapma', 'Açıklık'], 'z = (x − x̄) / σ dönüşümü pozitif çarpanlı doğrusal bir dönüşümdür; sıralamayı korur ama ortalama, standart sapma ve açıklığı değiştirir.'),
  ('Bir veri setindeki her değerin 5 eksiği alınırsa medyan mutlak sapma (MAD) nasıl değişir?', 'Değişmez', ['5 azalır', '5 katına çıkar', '25 azalır'], 'Medyan da 5 azalır; her değerin medyandan uzaklığı aynı kalır. Bu yüzden MAD değişmez.'),
  ('Bir sağlık bakanlığı günlük vaka sayılarını raporlarken çoğunlukla \'7 günlük ortalama\' kullanır. Bunun en önemli nedeni hangisidir?', 'Haftanın günlerine bağlı düzenli dalgalanmaları dengelemek', ['Toplam vaka sayısını azaltmak', 'Vaka sayılarının medyanını gizlemek', 'Verinin varyansını büyütmek'], 'Hafta sonu daha az test yapılması gibi haftalık döngüler günlük sayıları dalgalandırır. Yedi günlük pencere her gün türünden birer değer içerdiğinden bu etkiyi dengeler.'),
  ('Orta değeri 50 ve açıklığı 30 olan bir verinin en küçük değeri kaçtır?', '35', ['20', '65', '15'], 'En küçük + en büyük = 100 ve en büyük − en küçük = 30\'dur. Buradan en küçük değer (100 − 30) / 2 = 35 bulunur.'),
  ('Bir üniversite giriş sınavında Can\'ın yüzdelik dilimi \'%3\' olarak açıklanmıştır (en başarılı %3\'lük dilim). Can\'ın yüzdelik sırası yaklaşık kaçtır?', '97', ['3', '30', '33'], 'En başarılı %3\'te olmak, adayların yaklaşık %97\'sinin Can\'dan düşük puan aldığı anlamına gelir; yüzdelik sırası 97 olur.'),
  ('Bir verinin 10. yüzdeliği 12, 90. yüzdeliği 48\'dir. Verinin ortadaki yaklaşık %80\'inin bulunduğu aralığın genişliği kaçtır?', '36', ['30', '60', '24'], '10. ile 90. yüzdelik arasında gözlemlerin yaklaşık %80\'i yer alır; genişlik 48 − 12 = 36\'dır.'),
  ('Bir öğrencinin sınav puanı 85, yüzdelik sırası 85\'tir. Bu iki \'85\' için doğru yorum hangisidir?', 'Biri ham puanı, öteki öğrencilerin yaklaşık %85\'inin geride kaldığını gösterir', ['İkisi de aynı anlama gelir', 'Öğrenci soruların %85\'ini doğru yapmıştır, dolayısıyla tam puan almıştır', 'Öğrencinin puanı ortalamanın %85\'idir'], 'Ham puan sınavda alınan puandır; yüzdelik sıra ise bu puanın grubun içindeki göreli konumudur. Eşit çıkmaları rastlantıdır.'),
  ('20 kişilik bir grubun ortalaması 50, varyansı 16; 30 kişilik bir grubun ortalaması 60, varyansı 25\'tir. Birleşik grubun ortalaması kaçtır?', '56', ['55', '57,5', '54'], '(20 · 50 + 30 · 60) / 50 = (1000 + 1800) / 50 = 56.'),
  ('Bir veri setinde ortalama 30, medyan 30 ve mod 30\'dur. Bu bilgi aşağıdakilerden hangisini kesin olarak göstermez?', 'Verinin yayılımının küçük olduğunu', ['Medyanın 30 olduğunu', 'Ortalamanın 30 olduğunu', 'Gözlemlerin en az yarısının 30 ya da altında olduğunu'], 'Merkez ölçülerinin eşitliği yayılım hakkında bilgi vermez; veri 0\'dan 60\'a kadar geniş biçimde de dağılabilir.'),
  ('Gelir dağılımı gibi sağa çarpık verilerde ortalama ile medyan arasındaki farkın büyümesi neyi işaret eder?', 'Yüksek gelirli az sayıdaki kişinin ortalamayı yukarı çektiğini', ['Gelirlerin daha eşit dağıldığını', 'Düşük gelirlilerin sayısının azaldığını', 'Verinin sola çarpık hâle geldiğini'], 'Sağ kuyruk uzadıkça ortalama medyandan giderek uzaklaşır; fark, uçtaki yüksek değerlerin etkisinin bir göstergesidir.'),
  ('Bir köyde 9 hanenin yıllık geliri birbirine yakındır; 10. hane ise piyango kazanmıştır. Aşağıdaki ölçülerden hangisi bu olaydan en çok etkilenir?', 'Standart sapma', ['Medyan', 'Mod', 'Çeyrekler açıklığı'], 'Çok büyük tek bir değer kare sapmalar toplamını aşırı büyütür; standart sapma ortalamadan bile daha fazla etkilenir. Medyan, mod ve IQR dirençlidir.'),
  ('Rastgele seçilen beş otomobilin 100 km\'deki yakıt tüketimleri (desilitre) 42, 38, 45, 40, 35\'tir. Örneklem varyansı kaçtır?', '14,5', ['11,6', '3,81', '58'], 'Ortalama 40\'tır. Kare sapmalar 4, 4, 25, 0, 25 toplamı 58\'dir; 58 / 4 = 14,5. 11,6 ise n\'ye bölünmüş değerdir.'),
  ('Bir mağazanın yedi günlük müşteri sayıları 120, 135, 128, 142, 150, 131, 139\'dur. Çeyrekler açıklığı kaçtır? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', '14', ['30', '7', '12,5'], 'Sıralı veri 120, 128, 131, 135, 139, 142, 150\'dir. Alt yarı 120, 128, 131 → Q1 = 128; üst yarı 139, 142, 150 → Q3 = 142. IQR = 14; 30 ise açıklıktır.'),
  ('Ardışık 5 cm aralıklarla dizilmiş beş öğrencinin boyları 160, 165, 170, 175, 180 cm\'dir. Bu boylara en uzun öğrenciden 5 cm uzun yeni bir öğrenci eklenirse aşağıdakilerden hangisi değişmez?', 'Ardışık boylar arasındaki fark', ['Ortalama', 'Medyan', 'Açıklık'], 'Yeni veri 160–185 arasında 5\'er cm aralıklıdır; ardışık farklar yine 5 cm\'dir. Ortalama ve medyan 172,5\'e, açıklık 25\'e çıkar.'),
  ('Bir restoranın 20 müşterisi hizmeti 1–5 arası puanlamıştır: 1 puan 2 kişi, 2 puan 5 kişi, 3 puan 8 kişi, 4 puan 4 kişi, 5 puan 1 kişi. Ortalama puan kaçtır?', '2,85', ['3', '2,9', '3,15'], 'Toplam puan 2 + 10 + 24 + 16 + 5 = 57\'dir; 57 / 20 = 2,85.'),
  ('Bir ayakkabı mağazasında satılan 30 çiftin numaraları şöyledir: 36 numara 3, 37 numara 5, 38 numara 9, 39 numara 7, 40 numara 6 çift. Numaraların medyanı kaçtır?', '38', ['38,5', '39', '38,27'], '15. ve 16. değerler gerekir. Birikimli sayılar 3, 8, 17 olduğundan 9.–17. değerler 38\'dir; medyan 38 olur.'),
  ('Bir veride 2 değeri 4 kez, 4 değeri 2 kez, 6 değeri 4 kez görülmektedir. Bu veri için hangi ifade doğrudur?', 'İki modludur ve ortalaması 4\'tür', ['Tek modludur ve modu 4\'tür', 'Modu yoktur ve ortalaması 4\'tür', 'İki modludur ve ortalaması 3\'tür'], '2 ve 6\'nın frekansları eşit ve en büyüktür; veri iki modludur. Ortalama (8 + 8 + 24) / 10 = 4\'tür.'),
  ('Bir frekans dağılımında bütün frekanslar 3 ile çarpılırsa (her değer üç kat sıklıkla görülürse) ortalama nasıl değişir?', 'Değişmez', ['3 katına çıkar', '3 artar', '9 katına çıkar'], 'Ortalama Σfx / Σf\'dir; pay ve payda aynı çarpanla büyüdüğünden oran değişmez. Varyans ve medyan da aynı kalır.'),
  ('Bir veride her değerin frekansı aynıdır (ör. 4, 8, 12, 16\'nın her biri 5 kez). Bu durumda ortalama hangi basit hesapla bulunur?', 'Farklı değerlerin düz ortalamasıyla', ['Frekansların ortalamasıyla', 'En büyük frekansla', 'Frekansların toplamıyla'], 'Eşit frekanslar eşit ağırlık demektir; ağırlıklı ortalama, farklı değerlerin basit ortalamasına eşit olur: (4 + 8 + 12 + 16) / 4 = 10.'),
  ('Bir öğrenci \'Sınıf ortalaması 75, ben 80 aldım; demek ki sınıfın en az yarısından yüksek puan aldım\' diyor. Bu çıkarım için ne söylenebilir?', 'Kesin değildir; bunun için medyanı bilmek gerekir', ['Kesinlikle doğrudur', 'Kesinlikle yanlıştır', 'Yalnız standart sapma 5 ise doğrudur'], 'Ortalamanın üstünde olmak medyanın üstünde olmayı garanti etmez; sola çarpık bir dağılımda medyan 80\'in üstünde olabilir.'),
  ('Bir kargo firması \'ortalama teslim süremiz 2 gün\' diye reklam yapıyor; ancak bazı müşteriler 7 gün bekliyor. Müşteri açısından ortalamaya ek olarak hangi bilgi en yararlıdır?', 'Teslim sürelerinin yayılımı ya da 90. yüzdeliği', ['Teslim sürelerinin modunun karesi', 'Firmanın toplam teslimat sayısı', 'Teslim sürelerinin toplamı'], 'Yayılım ölçüleri ve üst yüzdelikler, bir müşterinin ne kadar uzun bekleyebileceğini gösterir; ortalama tek başına bu riski göstermez.'),
  ('Bir ülkede medyan hane geliri bir yılda artmıştır. Buna göre kesin olarak ne söylenebilir?', 'Ortadaki hanenin geliri öncekinden yüksektir', ['Bütün hanelerin geliri artmıştır', 'En yoksul hanelerin geliri artmıştır', 'Ortalama gelir de kesinlikle artmıştır'], 'Medyan yalnız sıralamanın ortasındaki değeri gösterir. Dağılımın uçlarında ne olduğu ya da ortalamanın yönü medyandan çıkarılamaz.'),
  ('Bir fabrika müdürü iki makineden birini seçecektir. İkisinin ürettiği parçaların ortalama çapı hedefe (20 mm) eşittir; A makinesinin standart sapması 0,1 mm, B\'ninki 0,5 mm\'dir. Tolerans ±0,3 mm ise hangisi seçilmelidir?', 'A', ['B', 'İkisi de aynı ölçüde uygundur', 'Hangisinin seçileceği yalnız ortalamaya bağlıdır'], 'A\'da sapmalar küçük olduğundan parçaların neredeyse tamamı ±0,3 mm içinde kalır; B\'de standart sapma toleransı aştığından çok sayıda hatalı parça çıkar.'),
  ('12, 15, 18, 20, 25 verisinden iki değer birlikte çıkarılacaktır. Hangi iki değer çıkarılırsa medyan değişmez?', '12 ve 25', ['15 ve 18', '18 ve 25', '12 ve 15'], 'En küçük ve en büyük değer birlikte çıkarılırsa ortadaki değer (18) yine ortada kalır.'),
  ('A verisi 1, 3, 5 ve B verisi 2, 4, 6, 8\'dir. İki veri birleştirilirse birleşik verinin medyanı kaç olur?', '4', ['3,5', '4,5', '5'], 'Birleşik sıralı veri 1, 2, 3, 4, 5, 6, 8\'dir; yedi değerin ortadakisi 4\'tür. Medyanların ortalaması (3 ile 5\'in ortalaması) değil, yeniden sıralama gerekir.'),
  ('Bir gözlemin ortalamadan uzaklığı iki katına çıkarsa bu gözlemin kare sapmalar toplamına katkısı nasıl değişir?', '4 katına çıkar', ['2 katına çıkar', 'Değişmez', 'Yarıya iner'], 'Katkı (x − x̄)² olduğundan uzaklık iki katına çıkınca katkı 2² = 4 katına çıkar. Varyansın uç değerlere duyarlılığı bundan kaynaklanır.'),
  ('Bir arkadaşınız ortancayla (medyanla) ilgili dört iddia sıralıyor. Bunlardan hangisi hatalıdır?', 'Verideki her değerin büyüklüğünü hesaba katar', ['Sıralı verinin ortasındaki konumu belirtir', 'Aykırı değerlere karşı dirençlidir', 'Sıralı kategorik verilerde kullanılabilir'], 'Medyan yalnız ortadaki konuma bağlıdır; diğer değerlerin büyüklüğü değişse de sıralama aynı kaldıkça medyan değişmez.'),
  ('Bir veri setine yeni bir gözlem eklendiğinde mod için aşağıdakilerden hangisi gerçekleşebilir?', 'Tek modlu veri iki modlu hâle gelebilir', ['Mod her zaman yeni gözleme eşit olur', 'Mod her zaman değişmeden kalır', 'Mod ortalamaya eşit olmak zorundadır'], 'Eklenen değer ikinci en sık değerin frekansını en sık değerinkine eşitlerse veri iki modlu olur. Yeni değerin konumu ve frekansına göre mod değişebilir ya da aynı kalabilir.'),
  ('Ölçeği sınıflayıcı olan bir değişken için aşağıdakilerden hangisi hesaplanamaz?', 'Medyan', ['Mod', 'Kategori frekansları', 'Kategori yüzdeleri'], 'Sınıflayıcı kategoriler sıralanamaz; bu yüzden ortadaki değer anlamsızdır. Frekans, yüzde ve mod ise hesaplanabilir.'),
  ('Bir manav 50 kg elmayı kilosu 1,2 dolardan, 30 kg armudu 1,5 dolardan, 20 kg ayvayı 2 dolardan almıştır. Meyvelerin kilogram başına ortalama alış fiyatı kaç dolardır?', '1,45', ['1,57', '1,5', '1,40'], 'Toplam maliyet 60 + 45 + 40 = 145 dolar, toplam kütle 100 kg\'dır; 145 / 100 = 1,45 dolar.'),
  ('Bir üniversitede mühendislik öğrencilerinin (%40) not ortalaması 3,2; diğer öğrencilerin (%60) not ortalaması 2,7\'dir. Tüm öğrencilerin not ortalaması kaçtır?', '2,9', ['2,95', '3,0', '2,85'], '0,40 · 3,2 + 0,60 · 2,7 = 1,28 + 1,62 = 2,90.'),
  ('Bir firma iki ürünün satış fiyatlarını ortalamak istiyor: A ürünü 10 TL\'den 900 adet, B ürünü 40 TL\'den 100 adet satılmıştır. Satılan bir ürünün ortalama fiyatı kaç TL\'dir?', '13', ['25', '20', '15,5'], 'Toplam gelir 9000 + 4000 = 13 000 TL, toplam adet 1000\'dir; ortalama 13 TL. Fiyatların düz ortalaması (25) satış miktarını hesaba katmaz.'),
  ('10, 11, 12, 13, 14, 15, 90 ve 10, 30, 50, 70, 90 verilerinin açıklıkları eşittir (80). Çeyrekler açıklıkları için hangisi doğrudur?', 'İkinci verinin IQR\'si çok daha büyüktür', ['Açıklıklar eşit olduğu için IQR\'ler de eşittir', 'Birinci verinin IQR\'si daha büyüktür', 'İkisinin IQR\'si de 80\'dir'], 'Birinci veride değerlerin çoğu 10–15 arasında sıkışmıştır (IQR = 4), tek uç değer açıklığı büyütür. İkinci veride değerler eşit aralıklıdır (IQR = 60).'),
  ('Aşağıdaki yayılım ölçülerinden hangisi bütün gözlemleri hesaba katar?', 'Standart sapma', ['Açıklık', 'Çeyrekler açıklığı', 'Medyan mutlak sapma'], 'Standart sapma her gözlemin ortalamadan uzaklığını kullanır. Açıklık yalnız iki ucu, IQR iki çeyreği, MAD ise medyan çevresindeki konumu kullanır.'),
  ('Bir veri setinin ortalama mutlak sapması 0 ise standart sapması kaçtır?', '0', ['1', 'Ortalamaya eşit', 'Hesaplanamaz'], 'Ortalama mutlak sapmanın 0 olması her değerin ortalamaya eşit olduğu anlamına gelir; bu durumda standart sapma da 0\'dır.'),
  ('Bir zekâ testinde z = 2 olan puan 130, z = −1 olan puan 85\'tir. Testin standart sapması kaçtır?', '15', ['45', '10', '22,5'], '130 − 85 = 45 puanlık fark 3 standart sapmaya eşittir; σ = 15 bulunur (ortalama 100).'),
  ('Ortalaması 60, standart sapması 12 olan bir sınavda 42 alan öğrencinin T-puanı (T = 50 + 10z) kaçtır?', '35', ['42', '45', '−15'], 'z = (42 − 60) / 12 = −1,5; T = 50 + 10 · (−1,5) = 35.'),
  ('T-puanlarına (T = 50 + 10z) dönüştürülmüş bir veri setinin ortalaması ve standart sapması nedir?', '50 ve 10', ['0 ve 1', '50 ve 1', '10 ve 50'], 'z-puanlarının ortalaması 0, standart sapması 1\'dir. Doğrusal dönüşümle ortalama 50 + 10 · 0 = 50, standart sapma 10 · 1 = 10 olur.'),
  ('Bir değerin z-puanı −2,5, bir başkasınınki 2\'dir. Ortalamaya göre hangisi daha olağan dışıdır?', 'z-puanı −2,5 olan', ['z-puanı 2 olan', 'İkisi eşit derecede olağan dışıdır', 'Ortalama bilinmeden karşılaştırılamaz'], 'Olağan dışılık ortalamadan standart sapma cinsinden uzaklığa bağlıdır: |−2,5| > |2|. İşaret yalnız yönü belirtir.'),
  ('Bir veri setindeki bütün değerlere 5 eklenirse her gözlemin z-puanı nasıl değişir?', 'Değişmez', ['5 artar', '5/σ artar', 'Sıfır olur'], 'Ortalama da 5 artar, standart sapma değişmez; böylece (x + 5 − (x̄ + 5)) / σ = (x − x̄) / σ olur.'),
  ('Bir bebeğin kütlesinin z-puanı 0,8, boyunun z-puanı −0,3\'tür (aynı yaştaki bebeklere göre). Buna göre hangisi doğrudur?', 'Kütlesi yaşıtlarının ortalamasının üstünde, boyu biraz altındadır', ['Bebeğin kütlesi 0,8 kg\'dır', 'Boyu ortalamadan 0,3 cm kısadır', 'Kütle ve boy aynı birimde olduğundan karşılaştırılamaz'], 'z-puanları birimsizdir; pozitif değer ortalamanın üstünü, negatif değer altını gösterir. Ham kütle ya da boy bilgisi vermez.'),
  ('Kareler ortalaması (karesel ortalama) nasıl hesaplanır?', 'Değerlerin karelerinin ortalamasının karekökü alınarak', ['Değerlerin ortalamasının karesi alınarak', 'Değerlerin çarpımının karekökü alınarak', 'Değerlerin terslerinin ortalaması alınarak'], 'Karesel ortalama √(Σx² / n)\'dir. Elektrikte etkin (RMS) değer bu biçimde hesaplanır.'),
  ('1 ve 7 sayılarının karesel ortalaması (√((1² + 7²) / 2)) kaçtır?', '5', ['4', '√7', '25'], '(1 + 49) / 2 = 25 ve √25 = 5\'tir. Aritmetik ortalama 4 olup karesel ortalamadan küçüktür.'),
  ('Bir koşucu eşit uzunluktaki üç turu saatte 6, 8 ve 12 km hızla koşuyor. Üç turun ortalama hızı saatte kaç km\'dir?', '8', ['8,67', '9', '7,5'], 'Eşit mesafelerde harmonik ortalama kullanılır: 3 / (1/6 + 1/8 + 1/12) = 3 / (9/24) = 8 km/sa.'),
  ('0,5 ile 8 sayılarının geometrik ortalaması kaçtır?', '2', ['4,25', '4', '1'], '√(0,5 · 8) = √4 = 2\'dir. Aritmetik ortalama 4,25 olup çok daha büyüktür.'),
  ('Bir hisse senedi bir ayda değerini iki katına çıkarıp sonraki ay yarıya düşmüştür. Aylık değişim çarpanlarının geometrik ortalaması kaçtır?', '1', ['1,25', '0,75', '1,5'], '√(2 · 0,5) = √1 = 1\'dir; yani ortalama aylık değişim %0\'dır ve hisse başlangıç değerine dönmüştür.'),
  ('Aşağıdaki durumların hangisinde harmonik ortalama kullanmak en uygundur?', 'Eşit tutarlarla farklı fiyatlardan alım yapıldığında birim fiyatı ortalamak', ['Yıllık büyüme oranlarını ortalamak', 'Sınav puanlarının sınıf ortalamasını bulmak', 'En sık satılan ürünü belirlemek'], 'Eşit tutar harcandığında alınan miktar fiyatla ters orantılıdır; ortalama birim fiyat harmonik ortalamayla bulunur. Büyüme oranları için geometrik ortalama uygundur.'),
  ('Ardışık yedi çift sayıdan oluşan 2, 4, 6, 8, 10, 12, 14 verisinin anakütle varyansı kaçtır? (1, 2, …, 7 verisinin anakütle varyansı 4\'tür.)', '16', ['4', '8', '18,67'], 'Veri, 1–7 verisinin her değerinin 2 ile çarpılmasıyla elde edilir. Varyans 2² = 4 katına çıkar: 4 · 4 = 16. 18,67 örneklem varyansıdır.'),
  ('10 gözlemli bir örneklemde ortalamadan sapmaların kareleri toplamı 120\'dir. Örneklem varyansı (n − 1 ile) yaklaşık kaçtır?', '13,33', ['12', '11,0', '10,95'], 's² = 120 / (10 − 1) ≈ 13,33. 12 ise n\'ye bölünerek bulunur.'),
  ('a > 0 olmak üzere a, 2a, 3a, 4a, 5a verisinin ortalaması 15\'tir. Bu verinin açıklığı kaçtır?', '20', ['15', '25', '4'], 'Ortalama 15a / 5 = 3a = 15 olduğundan a = 5\'tir. Açıklık 5a − a = 4a = 20.'),
  ('Gözlemleri x₁, x₂, …, xₙ olan bir veride Σ(xᵢ − 7) = 0 olduğu biliniyor. Verinin ortalaması kaçtır?', '7', ['0', 'n/7', '7n'], 'Σ(xᵢ − 7) = Σxᵢ − 7n = 0 ise Σxᵢ = 7n ve ortalama 7\'dir. Sapmaların toplamının sıfır olduğu nokta ortalamadır.'),
  ('Bir okul servisi şirketi, öğrencilerin evden okula yolculuk süresinin en uzun olduğu durumlara göre güzergâh planlayacaktır. Bu planlama için hangi istatistik en kritiktir?', 'Yüksek yüzdelikler', ['Ortalama süre', 'Medyan süre', 'En sık görülen süre'], 'Planlamada uzun yolculuklar belirleyicidir; üst yüzdelikler yolcuların çoğunun karşılaştığı en kötü durumu gösterir.'),
  ('Bir elektrik şirketi kapasite planlaması yaparken bir şehrin günlük ortalama tüketimine göre santral kuruyor. Bu yaklaşımın sakıncası nedir?', 'Tüketimin zirve yaptığı günlerde arz yetersiz kalabilir', ['Ortalama tüketim her zaman zirve tüketime eşittir', 'Ortalama tüketim hesaplanamaz', 'Tüketim verisi kategoriktir'], 'Ortalama, yüksek tüketimli günlerin altında kalır. Kapasite, yayılım ve en yüksek değerler dikkate alınarak belirlenmelidir.'),
  ('Bir veri setinde çok sayıda aykırı değer bulunuyor ve araştırmacı hem merkezi hem de yayılımı dirençli ölçülerle raporlamak istiyor. Hangisi uygundur?', 'Medyan ve medyan mutlak sapma', ['Ortalama ve varyans', 'Orta değer ve açıklık', 'Ortalama ve standart sapma'], 'Medyan ve MAD uç değerlerden çok az etkilenir; diğer çiftlerdeki ölçüler aykırı değerlere duyarlıdır.'),
  ('Bir dikiş atölyesinde altı terzinin bir günde diktiği gömlek sayıları 10, 14, 15, 17, 19, 21\'dir. Ortalama mutlak sapma kaçtır?', '3', ['2,5', '16', '3,56'], 'Ortalama 96 / 6 = 16\'dır. Mutlak sapmalar 6, 2, 1, 1, 3, 5 olup toplamları 18\'dir; 18 / 6 = 3.'),
  ('Bir mahallede altı ailenin sahip olduğu bisiklet sayıları 1, 2, 2, 3, 10, 12\'dir. Bu sayıların alt ve üst çeyrek değerleri hangileridir? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', '2 ve 10', ['1,5 ve 11', '2 ve 3', '2,5 ve 10'], 'Alt yarı 1, 2, 2 → Q1 = 2; üst yarı 3, 10, 12 → Q3 = 10. Medyan ise 2,5\'tir.'),
  ('Bir yüzme kulübünde sekiz sporcunun 50 m serbest dereceleri (saniye) 22, 25, 25, 28, 30, 32, 35, 39\'dur. En iyi ve en kötü derece atılarak hesaplanan kırpılmış ortalama yaklaşık kaçtır?', '29,17', ['29,5', '29', '30,5'], '22 ve 39 atılır. Kalan altı değerin toplamı 175\'tir; 175 / 6 ≈ 29,17 saniye. Kırpılmamış ortalama 29,5\'tir.'),
  ('Beş günlük bir kampta bir öğrencinin her gün yazdığı mektup sayıları 3, 8, 8, 9, 12\'dir. Bu beş gün anakütle kabul edilirse mektup sayılarının varyansı kaçtır?', '8,4', ['10,5', '2,9', '8'], 'Ortalama 40 / 5 = 8\'dir. Kare sapmalar 25, 0, 0, 1, 16 olup toplamı 42\'dir; 42 / 5 = 8,4. 10,5 örneklem varyansıdır.'),
  ('Bir veri setinde ortalama ile %20 kırpılmış ortalama arasında büyük bir fark bulunuyor. Bu durum en çok neye işaret eder?', 'Uçlarda aşırı değerler bulunduğuna', ['Verinin tam simetrik olduğuna', 'Bütün değerlerin eşit olduğuna', 'Gözlem sayısının çok büyük olduğuna'], 'Uçlardaki değerler atılınca ortalama belirgin biçimde değişiyorsa bu değerler ortalamayı güçlü biçimde etkiliyordur, yani aykırı ya da çarpık değerler vardır.'),
  ('Bir basketbol okulunda 20 öğrencinin boyları gruplanmıştır: 150–160 cm 4 öğrenci, 160–170 cm 10 öğrenci, 170–180 cm 6 öğrenci. Sınıf orta noktalarıyla tahmin edilen ortalama boy kaç cm\'dir?', '166', ['165', '167,5', '170'], 'Orta noktalar 155, 165, 175\'tir. (620 + 1650 + 1050) / 20 = 3320 / 20 = 166 cm.'),
  ('Bir sınavın puan dağılımı şöyledir: 0–25: 3, 25–50: 8, 50–75: 14, 75–100: 5 öğrenci. Medyan hangi sınıftadır?', '50–75', ['25–50', '75–100', '0–25'], '30 öğrencide medyan 15. ve 16. gözlemlerdir. Birikimli frekanslar 3, 11, 25 olduğundan 15. ve 16. gözlem 50–75 sınıfındadır.'),
  ('Gruplanmış veride sınıf genişliğinin çok büyük seçilmesinin merkez ölçüleri üzerindeki olası etkisi nedir?', 'Ayrıntı kaybolur ve tahminler kabalaşır', ['Ortalama her zaman tam doğru hesaplanır', 'Varyans sıfır olur', 'Medyan tanımsız hâle gelir'], 'Az sayıda geniş sınıf, gözlemlerin sınıf içindeki konumlarını gizler; orta noktalarla yapılan tahminler gerçek değerlerden daha fazla sapabilir.'),
  ('Çebişev eşitsizliğine göre bir veride ortalamadan 5 standart sapmadan daha uzak gözlemlerin oranı en çok ne kadar olabilir?', '%4', ['%5', '%20', '%0,04'], 'Bu oran en çok 1/k² = 1/25 = 0,04, yani %4\'tür.'),
  ('Bir sınıfta boyların ortalaması 165 cm, standart sapması 6 cm, kütlelerin ortalaması 60 kg, standart sapması 9 kg\'dır. Göreli değişkenliği daha büyük olan özellik hangisidir?', 'Kütle', ['Boy', 'İkisi eşittir', 'Birimler farklı olduğundan karşılaştırılamaz'], 'DK, boy için 6 / 165 ≈ %3,6; kütle için 9 / 60 = %15\'tir. Kütle göreli olarak çok daha değişkendir.'),
  ('A ve B ürünlerinin günlük satışlarının ortalamaları 200 ve 50, standart sapmaları 30 ve 10\'dur. Değişim katsayısı daha büyük olan ürün hangisidir ve DK değeri nedir?', 'B, %20', ['A, %15', 'B, %10', 'A, %30'], 'A\'nın DK\'si 30 / 200 = %15, B\'ninki 10 / 50 = %20\'dir.'),
  ('İki sınavda Deniz\'in z-puanları 1,8 ve 0,9\'dur. İkinci sınavda göreli konumunun birinciye göre nasıl değiştiği için doğru yorum hangisidir?', 'Sınıfına göre konumu gerilemiştir', ['Ham puanı kesinlikle düşmüştür', 'Ham puanı kesinlikle yarıya inmiştir', 'Göreli konumu değişmemiştir'], 'z-puanının düşmesi Deniz\'in sınıf ortalamasına göre daha az öne çıktığını gösterir; ham puanlar sınavların ortalama ve standart sapmalarına bağlı olduğundan kesin bir şey söylenemez.'),
  ('Bir telefon modelinin pil ömrü testinde 7 cihazın dayanma süreleri (saat) 18, 21, 19, 6, 20, 22, 19\'dur. 6 saatlik sonucun arızalı bir cihaza ait olduğu düşünülüyorsa tipik pil ömrünü hangi ölçü daha iyi yansıtır ve değeri nedir?', 'Medyan, 19 saat', ['Ortalama, 17,9 saat', 'Orta değer, 14 saat', 'Açıklık, 16 saat'], 'Sıralı veri 6, 18, 19, 19, 20, 21, 22\'dir; medyan 19 saattir. Arızalı cihaz ortalamayı 125 / 7 ≈ 17,9\'a düşürür.'),
  ('Bir okulda 1–5 arası verilen karne notlarının modu 4\'tür. Bu bilgi aşağıdakilerden hangisini gösterir?', 'En çok öğrencinin aldığı not 4\'tür', ['Öğrencilerin yarısı 4\'ün üstünde not almıştır', 'Not ortalaması 4\'tür', 'Öğrencilerin çoğunluğu (yarıdan fazlası) 4 almıştır'], 'Mod en sık görülen değerdir; 4 alan öğrencilerin sayısı diğer notlardan fazladır ama toplamın yarısını geçmesi gerekmez.'),
  ('Bir veri setinin ortalaması 0, varyansı 25\'tir. Her değerden 10 çıkarılıp sonuç 5\'e bölünürse yeni verinin ortalaması ve varyansı nedir?', '−2 ve 1', ['−2 ve 5', '0 ve 1', '2 ve 25'], 'y = (x − 10) / 5 için ortalama (0 − 10) / 5 = −2, varyans 25 / 5² = 1 olur.'),
  ('Bir apartmanın beş katındaki daire sayıları 9, 9, 9, 9, 14\'tür. Daire sayılarının anakütle standart sapması kaçtır?', '2', ['4', '2,24', '5'], 'Ortalama 50 / 5 = 10\'dur. Kare sapmalar 1, 1, 1, 1, 16 toplamı 20; varyans 20 / 5 = 4, standart sapma 2\'dir.'),
  ('Bir pazarlama ekibi rastgele seçtiği üç günde 100, 200 ve 300 sipariş almıştır. Bu örneklemin standart sapması (n − 1 ile) kaç sipariştir?', '100', ['81,6', '200', '10 000'], 'Ortalama 200\'dür. Kare sapmalar toplamı 10 000 + 0 + 10 000 = 20 000; örneklem varyansı 20 000 / 2 = 10 000, standart sapma 100\'dür.'),
  ('Bir yaz okulunda beş grubun öğrenci sayıları 12, 12, 18, 18, 20\'dir. Anakütle varyansı kaçtır?', '11,2', ['14', '3,35', '16'], 'Ortalama 80 / 5 = 16\'dır. Kare sapmalar 16, 16, 4, 4, 16 toplamı 56\'dır; 56 / 5 = 11,2.'),
  ('Beş öğrencinin nabız ölçümleri 64, 68, 72, 76, 80 olup varyansları 32\'dir. Ölçümler yanlışlıkla yarım dakikalık sayılarla kaydedildiğinde değerler 32, 34, 36, 38, 40 olur. Bu kaydın varyansı kaçtır?', '8', ['16', '32', '4'], 'İkinci veri birincinin yarısıdır. Varyans (1/2)² = 1/4 katına iner: 32 / 4 = 8.'),
  ('Varyans hesabında sapmaların mutlak değeri yerine karesinin alınmasının bir sonucu aşağıdakilerden hangisidir?', 'Büyük sapmalar sonuca orantısız biçimde fazla katkı yapar', ['Sonuç her zaman ortalama mutlak sapmaya eşit çıkar', 'Küçük sapmalar sonuca daha çok katkı yapar', 'Sonuç verinin birimiyle aynı birimde çıkar'], 'Kare alma büyük sapmaları daha da büyütür; örneğin 1\'lik sapma 1, 10\'luk sapma 100 katkı yapar. Bu yüzden varyans uç değerlere duyarlıdır.'),
  ('Bir veride ortalama 50, anakütle standart sapması 10\'dur. Değerlerin karelerinin ortalaması kaçtır?', '2600', ['2500', '2510', '100'], 'x² ortalaması = σ² + x̄² = 100 + 2500 = 2600.'),
  ('Gözlem sayısı 1 olan bir örneklem için n − 1 bölücülü örneklem varyansı neden hesaplanamaz?', 'Payda sıfır olur', ['Pay negatif olur', 'Ortalama tanımsızdır', 'Gözlem medyana eşittir'], 'n = 1 iken n − 1 = 0 olur ve sıfıra bölme tanımsızdır; tek gözlemden yayılım tahmin edilemez.'),
  ('Bir bisiklet kiralama noktasının yedi günlük kiralama sayıları 8, 10, 9, 13, 15, 14, 18\'dir. Üç günlük hareketli ortalamalar hesaplanırsa kaç değer elde edilir ve sonuncusu kaçtır?', '5 değer; sonuncusu yaklaşık 15,67', ['7 değer; sonuncusu 18', '5 değer; sonuncusu 14', '3 değer; sonuncusu yaklaşık 15,67'], '7 günlük seride 3\'lük pencere 7 − 3 + 1 = 5 kez kaydırılabilir. Son pencere 15, 14, 18 olup ortalaması 47 / 3 ≈ 15,67\'dir.'),
  ('Bir kargo deposunda sekiz günde gelen koli sayıları (yüz) 5, 9, 12, 14, 15, 20, 22, 30\'dur. Q1 ve Q3 sırasıyla kaçtır? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', '10,5 ve 21', ['9 ve 22', '12 ve 20', '10,5 ve 20'], 'Alt yarı 5, 9, 12, 14 → Q1 = (9 + 12) / 2 = 10,5. Üst yarı 15, 20, 22, 30 → Q3 = (20 + 22) / 2 = 21.'),
  ('Bir kooperatifte üç farklı süt tedarikçisinden günde 200, 300 ve 500 litre süt alınmaktadır. Sütün yağ oranları sırasıyla %3,0, %3,5 ve %4,0\'dır. Karışımın yağ oranı yüzde kaçtır?', '%3,65', ['%3,5', '%3,75', '%3,60'], '(200 · 3,0 + 300 · 3,5 + 500 · 4,0) / 1000 = (600 + 1050 + 2000) / 1000 = 3,65.'),
  ('1, 1, 2, 2, 3, 3 verisine hangi değer eklenirse veri tek modlu hâle gelir?', '1, 2 ya da 3\'ten biri', ['Yalnız 4', 'Yalnız 0', 'Herhangi bir değer'], 'Şu anda üç değerin frekansı da 2\'dir. Bunlardan birinin frekansı 3\'e çıkarsa o değer tek mod olur; yeni bir değer eklemek ise modu belirgin kılmaz.'),
  ('Bir veri setinin ortalaması 15 ve medyanı 12\'dir. Her değer 2 ile çarpılıp sonuca 5 eklenirse yeni ortalama ile yeni medyan arasındaki fark kaç olur?', '6', ['3', '11', '8'], 'Yeni ortalama 35, yeni medyan 29\'dur; fark 6 = 2 · 3 olur. Sabit eklemek farkı değiştirmez, çarpan farkı 2 katına çıkarır.'),
  ('Bir dağcılık kulübünde üyelerin çıktığı zirvelerin yükseklikleri metre cinsinden kaydedilmiştir. Kulüp kayıtları feet\'e (1 m ≈ 3,28 ft) çevirirse yüksekliklerin z-puanları nasıl değişir?', 'Değişmez', ['3,28 katına çıkar', '3,28\'e bölünür', 'Her biri 3,28 artar'], 'Birim değişikliği hem ortalamayı hem standart sapmayı aynı oranda büyütür; (x − x̄) / σ oranı aynı kalır.'),
  ('Bir girişim fuarındaki 50 stantta satılan ürün sayılarının ortalaması 40\'tır. Bir stantta yanlışlıkla 140 yerine 40 yazıldığı fark edilirse doğru ortalama kaç olur?', '42', ['40,5', '44', '38'], 'Yanlış toplam 2000\'dir. Doğru toplam 2000 − 40 + 140 = 2100 olup 2100 / 50 = 42.'),
  ('Bir veri setinin medyanı 40\'tır. Bu sayıdan büyük değerlerin her biri 10 artırılır, küçük değerler aynı bırakılırsa medyan nasıl değişir? (Medyana eşit tek bir orta değer vardır.)', 'Değişmez', ['10 artar', '5 artar', 'Azalır'], 'Ortadaki değer değişmediği ve büyük değerler büyüdükçe yine onun üstünde kaldığı için sıralama korunur; medyan 40 kalır.'),
  ('Bir mağazada aylık satış miktarlarının değişim katsayısı %40 bulunmuştur. Mağaza yöneticisi için en uygun yorum hangisidir?', 'Satışlar ortalamaya göre oldukça değişkendir', ['Satışlar her ay %40 artmaktadır', 'Satışların %40\'ı ortalamanın üstündedir', 'Ortalama satış 40 birimdir'], 'DK = σ / x̄ = 0,40, standart sapmanın ortalamanın %40\'ı kadar olduğunu gösterir; bu, göreli olarak yüksek bir değişkenliktir.'),
  ('Bir veri setinin varyansı 16 ve ortalaması 8\'dir. Değişim katsayısı yüzde kaçtır?', '%50', ['%200', '%25', '%2'], 'Standart sapma √16 = 4\'tür. DK = 4 / 8 = 0,5 = %50. Varyans doğrudan kullanılmaz.'),
  ('Aynı dokuz eczanenin reçete sayıları 28, 30, 34, 36, 39, 41, 45, 47, 52 olarak sıralanmıştır. Çeyrekler açıklığı kaçtır? (Çeyrekleri, medyanı yarılara katmadan alt ve üst yarının medyanı olarak alınız.)', '14', ['24', '11', '15,5'], 'Alt yarı 28, 30, 34, 36 → Q1 = 32; üst yarı 41, 45, 47, 52 → Q3 = 46. IQR = 14; 24 ise açıklıktır.'),
  ('Bir veri setinin bütün değerlerinin ortalamaya uzaklıkları eşittir ve bu uzaklık 4\'tür. Anakütle standart sapması ve ortalama mutlak sapma nedir?', 'İkisi de 4\'tür', ['Standart sapma 16, OMS 4\'tür', 'Standart sapma 2, OMS 4\'tür', 'İkisi de 16\'dır'], 'Her sapmanın mutlak değeri 4 ise mutlak sapmaların ortalaması 4, kare sapmaların ortalaması 16 ve karekökü 4\'tür.'),
  ('Bir öğrencinin 10 matematik ödevinin ortalaması 8,5\'tir. Öğretmen en düşük notu (4) hesaptan çıkarıyor. Yeni ortalama kaçtır?', '9', ['8,9', '9,5', '8,95'], 'Toplam 85\'tir. 4 çıkarılınca 81 kalır ve 81 / 9 = 9 bulunur.'),
  ('Bir fabrikada üç vardiyanın saatlik üretim ortalamaları 120, 150 ve 90 parçadır; vardiyalar sırasıyla 8, 8 ve 4 saat sürmektedir. Günlük saatlik ortalama üretim kaçtır?', '126', ['120', '130', '125,5'], 'Toplam üretim 960 + 1200 + 360 = 2520 parça, toplam süre 20 saattir; 2520 / 20 = 126 parça/saat.'),
  ('Aynı ürünü satan dört markette fiyatlar 24, 27, 25 ve 28 TL\'dir. Fiyatların ortalamadan sapmalarının kareleri toplamı kaçtır?', '10', ['2,5', '0', '14'], 'Ortalama 104 / 4 = 26\'dır. Sapmalar −2, 1, −1, 2; kareleri 4, 1, 1, 4 olup toplamı 10\'dur.'),
  ('Bir veri setinde Q1 = 18, medyan = 25, Q3 = 32\'dir. Ortadaki %50\'lik dilimin simetrisi için ne söylenebilir?', 'Medyana göre simetriktir', ['Sağa çarpıktır', 'Sola çarpıktır', 'Simetri hakkında bilgi yoktur'], 'Q1 ve Q3 medyandan eşit uzaklıktadır (7); bu, orta dilimin medyana göre simetrik olduğunu gösterir. Uçlar hakkında ayrıca bilgi gerekir.'),
  ('Bir öğrenci birinci dönem 5 dersin ortalamasını 80, ikinci dönem 7 dersin ortalamasını 86 olarak almıştır. Bütün derslerin (dersler eşit ağırlıklı) yıllık ortalaması kaçtır?', '83,5', ['83', '84', '82,5'], '(5 · 80 + 7 · 86) / 12 = (400 + 602) / 12 = 1002 / 12 = 83,5.'),
];
